window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["cloudwatch"]=[{"id":"cloudwatch-f0001","card":"q-cloudwatch-001-purpose-and-audience","sec":"cloudwatch-s002","q":"What is AWS CloudWatch, and who is it for?","a":"<p>CloudWatch is the monitoring and observability service for AWS resources, applications and services. It serves DevOps engineers, developers, IT managers and security specialists.</p>","hand":true},{"id":"cloudwatch-f0002","card":"q-cloudwatch-001-purpose-and-audience","sec":"cloudwatch-s002","q":"What does a CloudWatch course teach about metrics, canaries, X-Ray and RUM?","a":"<p>How to derive insights and take actions from metrics. How to use canaries to watch website and API health. How to use X-Ray for end-to-end tracing and RUM for real-user monitoring.</p>","hand":true},{"id":"cloudwatch-f0003","card":"q-cloudwatch-002-four-capabilities","sec":"cloudwatch-s003","q":"What are the four main capabilities of CloudWatch?","a":"<p>Comprehensive monitoring, infrastructure troubleshooting, proactive optimization and log analytics.</p>","hand":true},{"id":"cloudwatch-f0004","card":"q-cloudwatch-002-four-capabilities","sec":"cloudwatch-s003","q":"What does \"comprehensive monitoring\" mean in CloudWatch?","a":"<p>CloudWatch collects logs, metrics and events into one view, for example CPU, memory and network for EC2.</p>","hand":true},{"id":"cloudwatch-f0005","card":"q-cloudwatch-002-four-capabilities","sec":"cloudwatch-s003","q":"How does CloudWatch help with infrastructure troubleshooting?","a":"<p>It links metrics with logs and integrates with X-Ray for end-to-end visibility.</p>","hand":true},{"id":"cloudwatch-f0006","card":"q-cloudwatch-002-four-capabilities","sec":"cloudwatch-s003","q":"How does CloudWatch support proactive optimization?","a":"<p>Alarms compare metrics with thresholds (or ML-based anomaly bands) and trigger actions such as scaling.</p>","hand":true},{"id":"cloudwatch-f0007","card":"q-cloudwatch-002-four-capabilities","sec":"cloudwatch-s003","q":"What is the log analytics capability of CloudWatch?","a":"<p>Real-time log analysis with a purpose-built query language (Logs Insights) to find root causes.</p>","hand":true},{"id":"cloudwatch-f0008","card":"q-cloudwatch-003-benefits","sec":"cloudwatch-s004","q":"What benefits does CloudWatch bring to operations?","a":"<p>Faster time to resolution through quick log visualization. Better performance through proactive monitoring. One consolidated view for operations.</p>","hand":true},{"id":"cloudwatch-f0009","card":"q-cloudwatch-004-metrics-vs-logs","sec":"cloudwatch-s005","q":"In CloudWatch, what is the difference between metrics and logs?","a":"<p>Metrics show how often something happens. Logs reveal what happened.</p>","hand":true},{"id":"cloudwatch-f0010","card":"q-cloudwatch-004-metrics-vs-logs","sec":"cloudwatch-s005","q":"When do you use metrics and when do you use logs in CloudWatch?","a":"<p>Use metrics for trends and alarms. Use logs for diagnosis.</p>","hand":true},{"id":"cloudwatch-f0011","card":"q-cloudwatch-005-serverless-api-used-for-demos","sec":"cloudwatch-s006","q":"How do you create the serverless API backend used for CloudWatch demos?","a":"<p>Lambda console &gt; Applications &gt; Create application &gt; \"Serverless API backend\". This creates API Gateway, DynamoDB and Lambda functions.</p>","hand":true},{"id":"cloudwatch-f0012","card":"q-cloudwatch-005-serverless-api-used-for-demos","sec":"cloudwatch-s006","q":"Which settings does the CloudWatch demo API use when it is created?","a":"<p>Example name <code>cloudwatchcourseapi</code>, runtime Node.js, source control CodeCommit, and \"Create roles and permissions boundary\" ticked.</p>","hand":true},{"id":"cloudwatch-f0013","card":"q-cloudwatch-006-sample-client-app-that-generates-traffic","sec":"cloudwatch-s007","q":"Which commands start the sample client app that sends traffic to the demo API?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm install\nnode server.js</code></pre></div>","hand":true},{"id":"cloudwatch-f0014","card":"q-cloudwatch-006-sample-client-app-that-generates-traffic","sec":"cloudwatch-s007","q":"Where do you put the API endpoint for the sample client app, and in what form?","a":"<p>In the <code>.env</code> file:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>API_ENDPOINT=&quot;your-api-endpoint-from-aws&quot;</code></pre></div>","hand":true},{"id":"cloudwatch-f0015","card":"q-cloudwatch-006-sample-client-app-that-generates-traffic","sec":"cloudwatch-s007","q":"What is the default success rate of the sample traffic app, and what does \"Fail all requests\" do?","a":"<p>By default 2 of every 3 requests succeed and 1 fails. \"Fail all requests\" produces only errors.</p>","hand":true},{"id":"cloudwatch-f0016","card":"q-cloudwatch-006-sample-client-app-that-generates-traffic","sec":"cloudwatch-s007","q":"How many requests should you send with the sample app before opening the CloudWatch console, and what goes wrong with a bad endpoint?","a":"<p>Run 1,000 or 10,000 requests to build up metrics, then wait a few minutes. A wrong endpoint in <code>.env</code> means no logs.</p>","hand":true},{"id":"cloudwatch-f0017","card":"q-cloudwatch-007-what-a-metric-is","sec":"cloudwatch-s008","q":"What is a CloudWatch metric?","a":"<p>A time-ordered set of data points pushed to CloudWatch. It represents a monitored variable over time, such as API latency or Lambda invocations.</p>","hand":true},{"id":"cloudwatch-f0018","card":"q-cloudwatch-008-namespaces","sec":"cloudwatch-s009","q":"What is a CloudWatch namespace, and what are the two kinds?","a":"<p>A namespace holds metrics. AWS namespaces hold metrics from services (<code>AWS/ApiGateway</code>, <code>AWS/Lambda</code>, <code>AWS/EC2</code>, DynamoDB). Custom namespaces hold user-defined metrics.</p>","hand":true},{"id":"cloudwatch-f0019","card":"q-cloudwatch-008-namespaces","sec":"cloudwatch-s009","q":"What is the console path to find a metric, and how do you change its statistic and period?","a":"<p>CloudWatch &gt; Metrics &gt; All metrics &gt; pick namespace &gt; dimension (for example By Api Name, By Function Name) &gt; metric. Use Graphed metrics to change the statistic (Average vs Sum) and the period (5 minutes down to 1 second).</p>","hand":true},{"id":"cloudwatch-f0020","card":"q-cloudwatch-008-namespaces","sec":"cloudwatch-s009","q":"Why should you clear old selections in the CloudWatch metrics console?","a":"<p>So graphs do not accumulate previous metrics.</p>","hand":true},{"id":"cloudwatch-f0021","card":"q-cloudwatch-009-reading-api-gateway-latency-with-get-met","sec":"cloudwatch-s010","q":"Which boto3 call reads API Gateway latency using a metric query, and which namespace, metric and dimension does it use?","a":"<p><code>get_metric_data</code> with <code>MetricDataQueries</code>. Namespace <code>AWS/ApiGateway</code>, metric <code>Latency</code>, dimension <code>ApiName</code> with value <code>cloudwatchcourseapi</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>response = cloudwatch.get_metric_data(\n    MetricDataQueries=[</code></pre></div>","hand":true},{"id":"cloudwatch-f0022","card":"q-cloudwatch-009-reading-api-gateway-latency-with-get-met","sec":"cloudwatch-s010","q":"In the <code>get_metric_data</code> latency query, what do <code>Period</code> and <code>Stat</code> set, and how is the time range given?","a":"<p><code>Period</code> is 60 (seconds) and <code>Stat</code> is <code>Average</code>. The range is <code>StartTime</code> 60 minutes ago to <code>EndTime</code> now:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&#x27;Period&#x27;: 60,\n&#x27;Stat&#x27;: &#x27;Average&#x27;</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>StartTime=datetime.utcnow() - timedelta(minutes=60),\nEndTime=datetime.utcnow()</code></pre></div>","hand":true},{"id":"cloudwatch-f0023","card":"q-cloudwatch-010-reading-lambda-errors-with-get-metric-st","sec":"cloudwatch-s011","q":"How do you see the total number of Lambda errors over a period in CloudWatch?","a":"<p>Switch the aggregation from Average to Sum.</p>","hand":true},{"id":"cloudwatch-f0024","card":"q-cloudwatch-010-reading-lambda-errors-with-get-metric-st","sec":"cloudwatch-s011","q":"Which boto3 call reads the Sum of Lambda <code>Errors</code> for a function over 5-minute periods?","a":"<p><code>get_metric_statistics</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>response = cloudwatch.get_metric_statistics(\n    Namespace=&#x27;AWS/Lambda&#x27;,\n    MetricName=&#x27;Errors&#x27;,\n    Dimensions=[{&#x27;Name&#x27;: &#x27;FunctionName&#x27;, &#x27;Value&#x27;: &#x27;putItemFunction&#x27;}],\n    Period=300,\n    Statistics=[&#x27;Sum&#x27;]\n)\nprint(response[&#x27;Datapoints&#x27;])</code></pre></div>","hand":true},{"id":"cloudwatch-f0025","card":"q-cloudwatch-011-why-custom-metrics","sec":"cloudwatch-s012","q":"Why use custom metrics in CloudWatch when built-in metrics exist?","a":"<p>Built-in metrics are a foundation. Custom metrics capture business-specific data points such as order processing time or response time per endpoint.</p>","hand":true},{"id":"cloudwatch-f0026","card":"q-cloudwatch-011-why-custom-metrics","sec":"cloudwatch-s012","q":"Can custom metrics sit on the same dashboard as built-in metrics, and how do you publish them?","a":"<p>Yes, they can share a dashboard. Publish them with the AWS CLI, the CloudWatch API or an SDK.</p>","hand":true},{"id":"cloudwatch-f0027","card":"q-cloudwatch-012-resolution","sec":"cloudwatch-s013","q":"What are standard and high resolution for CloudWatch custom metrics?","a":"<p>Standard resolution is 1-minute granularity (the default). High resolution is 1-second granularity for time-sensitive metrics.</p>","hand":true},{"id":"cloudwatch-f0028","card":"q-cloudwatch-012-resolution","sec":"cloudwatch-s013","q":"How do you set high resolution on a custom metric, and what is the caveat?","a":"<p>Set <code>StorageResolution: 1</code>. It costs more and is not always needed.</p>","hand":true},{"id":"cloudwatch-f0029","card":"q-cloudwatch-013-publishing-with-boto3","sec":"cloudwatch-s014","q":"Which boto3 call publishes a custom metric, and what does it need?","a":"<p><code>put_metric_data</code> with a <code>Namespace</code> and a <code>MetricData</code> list.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>cloudwatch.put_metric_data(\n    Namespace=&#x27;MyApp/CustomMetrics&#x27;,\n    MetricData=[</code></pre></div>","hand":true},{"id":"cloudwatch-f0030","card":"q-cloudwatch-013-publishing-with-boto3","sec":"cloudwatch-s014","q":"What fields describe a custom metric datum in the boto3 <code>put_metric_data</code> example?","a":"<p><code>MetricName</code>, <code>Value</code>, <code>Unit</code>, <code>Timestamp</code> and <code>StorageResolution</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&#x27;MetricName&#x27;: &#x27;OrderProcessingTime&#x27;,\n&#x27;Value&#x27;: 150.0,\n&#x27;Unit&#x27;: &#x27;Milliseconds&#x27;,\n&#x27;Timestamp&#x27;: datetime.utcnow(),\n&#x27;StorageResolution&#x27;: 1</code></pre></div>","hand":true},{"id":"cloudwatch-f0031","card":"q-cloudwatch-014-publishing-from-a-node-js-app-setup","sec":"cloudwatch-s015","q":"Which npm packages does a Node.js app need to publish CloudWatch custom metrics?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm install @aws-sdk/client-cloudwatch @aws-sdk/credential-provider-node</code></pre></div>","hand":true},{"id":"cloudwatch-f0032","card":"q-cloudwatch-014-publishing-from-a-node-js-app-setup","sec":"cloudwatch-s015","q":"How do you set up IAM for a Node.js app that pushes custom metrics?","a":"<p>Create a customer-managed policy (for example <code>cloudwatchcustommetric</code>) with only <code>PutMetricData</code> under CloudWatch write access. Create an IAM user (for example <code>pushcustommetrics</code>) with no console access, attach the policy, and create an access key for local code.</p>","hand":true},{"id":"cloudwatch-f0033","card":"q-cloudwatch-014-publishing-from-a-node-js-app-setup","sec":"cloudwatch-s015","q":"Which values go into <code>.env</code> for the Node.js custom metric publisher?","a":"<p>The access key, secret key, region and namespace (placeholders only, never commit real keys):</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">.env</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>AWS_ACCESS_KEY_ID=your-access-key-id\nAWS_SECRET_ACCESS_KEY=your-secret-access-key\nAWS_REGION=us-east-1\nNAMESPACE=CloudWatchApiCourse</code></pre></div>","hand":true},{"id":"cloudwatch-f0034","card":"q-cloudwatch-015-publishing-from-a-node-js-app-cloudwatch","sec":"cloudwatch-s016","q":"What does each datum contain in the Node.js <code>cloudwatchMetrics.js</code> publisher?","a":"<p>A name, dimensions (environment, endpoint, HTTP method), timestamp, value and unit. The namespace groups the metrics.</p>","hand":true},{"id":"cloudwatch-f0035","card":"q-cloudwatch-015-publishing-from-a-node-js-app-cloudwatch","sec":"cloudwatch-s016","q":"How does <code>cloudwatchMetrics.js</code> create the CloudWatch client?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const cloudwatchClient = new CloudWatchClient({\n  region: process.env.AWS_REGION,\n  credentials: fromNodeProviderChain()\n});</code></pre></div>","hand":true},{"id":"cloudwatch-f0036","card":"q-cloudwatch-015-publishing-from-a-node-js-app-cloudwatch","sec":"cloudwatch-s016","q":"How does <code>publishMetric</code> in Node.js send a metric and handle failure?","a":"<p>It builds the parameters, creates a <code>PutMetricDataCommand</code> and sends it, inside try/catch that logs publishing failures:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const command = new PutMetricDataCommand(params);\nawait cloudwatchClient.send(command);</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>} catch (error) {\n  console.error(&#x27;Error publishing metric:&#x27;, error);\n}</code></pre></div>","hand":true},{"id":"cloudwatch-f0037","card":"q-cloudwatch-016-publishing-from-a-node-js-app-measuring","sec":"cloudwatch-s017","q":"How does the Node.js demo measure response time before publishing it as a metric?","a":"<p>It records <code>Date.now()</code> before the request and subtracts it after the response:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const startTime = Date.now();\nconst response = await axios.get(process.env.API_ENDPOINT);\nconst responseTime = Date.now() - startTime;</code></pre></div>","hand":true},{"id":"cloudwatch-f0038","card":"q-cloudwatch-016-publishing-from-a-node-js-app-measuring","sec":"cloudwatch-s017","q":"Which dimensions and call publish <code>ResponseTime</code> in the Node.js demo?","a":"<p>Dimensions <code>Environment</code>, <code>Endpoint</code> and <code>HttpMethod</code>, then <code>publishMetric</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ Name: &#x27;Environment&#x27;, Value: &#x27;Production&#x27; },\n{ Name: &#x27;Endpoint&#x27;, Value: &#x27;/api&#x27; },\n{ Name: &#x27;HttpMethod&#x27;, Value: &#x27;GET&#x27; }</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>await publishMetric(&#x27;ResponseTime&#x27;, responseTime, &#x27;Milliseconds&#x27;, dimensions);</code></pre></div>","hand":true},{"id":"cloudwatch-f0039","card":"q-cloudwatch-016-publishing-from-a-node-js-app-measuring","sec":"cloudwatch-s017","q":"What do you check if the Node.js app publishes no custom metrics?","a":"<p>Re-check the <code>.env</code> values: keys, region and namespace. Run <code>node server.js</code>, send requests, and watch the console for success or error messages.</p>","hand":true},{"id":"cloudwatch-f0040","card":"q-cloudwatch-017-viewing-custom-metrics","sec":"cloudwatch-s018","q":"How do you view a published custom metric in the CloudWatch console?","a":"<p>CloudWatch &gt; Metrics &gt; All metrics &gt; custom namespace &gt; choose dimensions (Endpoint, Environment, HttpMethod) &gt; <code>ResponseTime</code>.</p>","hand":true},{"id":"cloudwatch-f0041","card":"q-cloudwatch-017-viewing-custom-metrics","sec":"cloudwatch-s018","q":"Which statistic and period suit viewing small custom metric values, and why add dimensions?","a":"<p>Use Statistic Sum and a short period (such as 5 seconds) in Graphed metrics to see recent data. Dimensions add context so you can filter and slice the metric.</p>","hand":true},{"id":"cloudwatch-f0042","card":"q-cloudwatch-018-what-streaming-gives-you","sec":"cloudwatch-s019","q":"What is a CloudWatch metric stream?","a":"<p>A stream that sends metrics continuously to other services for deeper analytics beyond CloudWatch monitoring.</p>","hand":true},{"id":"cloudwatch-f0043","card":"q-cloudwatch-018-what-streaming-gives-you","sec":"cloudwatch-s019","q":"Which destinations can a CloudWatch metric stream use?","a":"<p>Amazon S3 (through Kinesis Data Firehose), Amazon Redshift, HTTP endpoints, and third parties such as Logz.io or MongoDB Cloud.</p>","hand":true},{"id":"cloudwatch-f0044","card":"q-cloudwatch-018-what-streaming-gives-you","sec":"cloudwatch-s019","q":"Which namespaces can a metric stream include?","a":"<p>All namespaces or selected ones. You can also exclude namespaces.</p>","hand":true},{"id":"cloudwatch-f0045","card":"q-cloudwatch-019-creating-a-stream-in-the-console","sec":"cloudwatch-s020","q":"What are the steps to create a metric stream in the console?","a":"<p>CloudWatch &gt; Metrics &gt; Streams &gt; Create metric stream.</p>\n<ol>\n  <li>Choose all namespaces or specific ones.</li>\n  <li>Choose the destination.</li>\n  <li>Name the stream (for example <code>streamdemo</code>) and create it.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0046","card":"q-cloudwatch-019-creating-a-stream-in-the-console","sec":"cloudwatch-s020","q":"What are the three destination options when creating a metric stream in the console?","a":"<p>Quick S3 setup auto-creates a Firehose, an S3 bucket and IAM roles. An existing Firehose. A custom Firehose.</p>","hand":true},{"id":"cloudwatch-f0047","card":"q-cloudwatch-019-creating-a-stream-in-the-console","sec":"cloudwatch-s020","q":"What source must a custom Firehose use for a CloudWatch metric stream?","a":"<p>Direct PUT. It is required for CloudWatch to send metrics.</p>","hand":true},{"id":"cloudwatch-f0048","card":"q-cloudwatch-020-creating-a-stream-with-boto3","sec":"cloudwatch-s021","q":"Which boto3 call creates a metric stream for one namespace and sends it to Firehose as JSON?","a":"<p><code>create_metric_stream</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>response = cloudwatch.create_metric_stream(\n    Name=&#x27;streamdemo&#x27;,\n    IncludeFilters=[{&#x27;Namespace&#x27;: &#x27;CloudWatchApiCourse&#x27;}],\n    OutputFormat=&#x27;json&#x27;\n)\nprint(response)</code></pre></div>","hand":true},{"id":"cloudwatch-f0049","card":"q-cloudwatch-020-creating-a-stream-with-boto3","sec":"cloudwatch-s021","q":"Which parameters of <code>create_metric_stream</code> name the Firehose and the IAM role?","a":"<p><code>FirehoseArn</code> and <code>RoleArn</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FirehoseArn=&#x27;arn:aws:firehose:us-east-1:account-id:deliverystream/metrics-streams-streamdemo&#x27;,\nRoleArn=&#x27;arn:aws:iam::account-id:role/CloudWatch-Metrics-Stream-Role&#x27;,</code></pre></div>","hand":true},{"id":"cloudwatch-f0050","card":"q-cloudwatch-021-verifying-a-stream","sec":"cloudwatch-s022","q":"How do you verify that a CloudWatch metric stream works?","a":"<p>Generate traffic (for example 100 requests). Check the stream status and destination, then the Firehose metrics (Incoming Bytes, Put Requests, Incoming Records, Data Sent to S3), then the S3 bucket.</p>","hand":true},{"id":"cloudwatch-f0051","card":"q-cloudwatch-021-verifying-a-stream","sec":"cloudwatch-s022","q":"How long can a metric stream take to deliver data, and why?","a":"<p>Data is batched, so it can take 1-2 minutes to appear. The Firehose may need about 5 minutes to become fully active.</p>","hand":true},{"id":"cloudwatch-f0052","card":"q-cloudwatch-021-verifying-a-stream","sec":"cloudwatch-s022","q":"What do you check if no data arrives from a metric stream?","a":"<p>Make sure the app is running and the IAM roles for Firehose and S3 are correct.</p>","hand":true},{"id":"cloudwatch-f0053","card":"q-cloudwatch-022-using-streamed-data","sec":"cloudwatch-s023","q":"What can you do with metric stream data in S3?","a":"<p>Query it with Athena, load it to Redshift for warehousing, or send it to third-party analytics.</p>","hand":true},{"id":"cloudwatch-f0054","card":"q-cloudwatch-022-using-streamed-data","sec":"cloudwatch-s023","q":"What are the tips for working with metric streams?","a":"<p>Monitor Firehose metrics for consistent delivery and test with a small number of requests first.</p>","hand":true},{"id":"cloudwatch-f0055","card":"q-cloudwatch-023-running-a-query","sec":"cloudwatch-s024","q":"How do you run a query in CloudWatch Logs Insights?","a":"<p>CloudWatch &gt; Logs &gt; Logs Insights. Pick the timeframe (default last 1 hour; use Custom for others), pick the log group, then write and run the query.</p>","hand":true},{"id":"cloudwatch-f0056","card":"q-cloudwatch-023-running-a-query","sec":"cloudwatch-s024","q":"Why does Logs Insights need a log group, and why limit results?","a":"<p>Each service writes to its own log group, for example the Lambda \"Put Item Function\" group. Limiting results reduces query cost, since more results cost more.</p>","hand":true},{"id":"cloudwatch-f0057","card":"q-cloudwatch-023-running-a-query","sec":"cloudwatch-s024","q":"What do you do if a Logs Insights query shows nothing in the demo?","a":"<p>Generate successful and failed requests first.</p>","hand":true},{"id":"cloudwatch-f0058","card":"q-cloudwatch-024-displaying-fields","sec":"cloudwatch-s025","q":"Which Logs Insights query shows the message field of up to 100 log events?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>fields @message\n| limit 100</code></pre></div>","hand":true},{"id":"cloudwatch-f0059","card":"q-cloudwatch-025-filtering","sec":"cloudwatch-s026","q":"How do you filter Logs Insights results for a keyword?","a":"<p>Chain commands with <code>|</code> and use <code>like</code> with a regex:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>fields @message\n| filter @message like /exception/</code></pre></div>","hand":true},{"id":"cloudwatch-f0060","card":"q-cloudwatch-025-filtering","sec":"cloudwatch-s026","q":"What do you do with a Logs Insights result to read the full error?","a":"<p>Expand the result to read the full error and stack trace. An example hit: <code>Validation exception: One or more parameter values were invalid, missing key ID in the payload</code>.</p>","hand":true},{"id":"cloudwatch-f0061","card":"q-cloudwatch-026-aggregating","sec":"cloudwatch-s027","q":"Which Logs Insights query counts the log events that contain \"exception\"?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>fields @message\n| filter @message like /exception/\n| stats count(*) as error_count</code></pre></div>","hand":true},{"id":"cloudwatch-f0062","card":"q-cloudwatch-026-aggregating","sec":"cloudwatch-s027","q":"How do you see error trends over time in Logs Insights?","a":"<p>Group into time buckets with <code>by bin(5m)</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>| stats count(*) as error_count by bin(5m)</code></pre></div>","hand":true},{"id":"cloudwatch-f0063","card":"q-cloudwatch-027-command-summary-and-typical-workflow","sec":"cloudwatch-s028","q":"What do <code>fields</code>, <code>filter</code>, <code>stats</code> and <code>by bin(5m)</code> do in Logs Insights?","a":"<p><code>fields @message</code> selects fields. <code>filter @message like /keyword/</code> filters. <code>stats count(*) as error_count</code> aggregates. <code>by bin(5m)</code> groups by time.</p>","hand":true},{"id":"cloudwatch-f0064","card":"q-cloudwatch-027-command-summary-and-typical-workflow","sec":"cloudwatch-s028","q":"Which other aggregations can Logs Insights <code>stats</code> use besides count?","a":"<p><code>sum</code>, <code>avg</code>, <code>max</code> and <code>min</code>.</p>","hand":true},{"id":"cloudwatch-f0065","card":"q-cloudwatch-027-command-summary-and-typical-workflow","sec":"cloudwatch-s028","q":"What is the workflow to investigate a validation exception from a missing ID parameter in Logs Insights?","a":"<p>Filter on <code>exception</code>, read the stack trace for the source, then aggregate by <code>bin(5m)</code> to see frequency.</p>","hand":true},{"id":"cloudwatch-f0066","card":"q-cloudwatch-028-common-query-with-timestamp-and-sort","sec":"cloudwatch-s029","q":"Which Logs Insights query shows the latest 100 ERROR messages with timestamps?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>fields @timestamp, @message\n| filter @message like /ERROR/\n| sort @timestamp desc\n| limit 100</code></pre></div>","hand":true},{"id":"cloudwatch-f0067","card":"q-cloudwatch-029-why-convert-logs-to-metrics","sec":"cloudwatch-s030","q":"Why convert CloudWatch logs to metrics?","a":"<p>A metric is quicker and more visual than repeatedly querying logs. An example is counting <code>ValidationException</code> errors from the <code>putItem</code> Lambda function over time.</p>","hand":true},{"id":"cloudwatch-f0068","card":"q-cloudwatch-030-creating-a-metric-filter","sec":"cloudwatch-s031","q":"What are the steps to create a metric filter?","a":"<ol>\n  <li>CloudWatch &gt; Logs &gt; Log groups &gt; select the group &gt; Metric filters &gt; Create metric filter.</li>\n  <li>Confirm the log streams have recent events.</li>\n  <li>Define the filter pattern.</li>\n  <li>Test the pattern.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0069","card":"q-cloudwatch-030-creating-a-metric-filter","sec":"cloudwatch-s031","q":"What kinds of filter patterns can a metric filter use?","a":"<p>Match terms (<code>error</code>, <code>warning</code>), JSON properties (<code>errorType = ValidationException</code>), or status codes (<code>statusCode = 500</code>).</p>","hand":true},{"id":"cloudwatch-f0070","card":"q-cloudwatch-030-creating-a-metric-filter","sec":"cloudwatch-s031","q":"Which metric filter pattern matches JSON events whose <code>errorType</code> is <code>ValidationException</code>?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{ $.errorType = &quot;ValidationException&quot; }</code></pre></div>","hand":true},{"id":"cloudwatch-f0071","card":"q-cloudwatch-030-creating-a-metric-filter","sec":"cloudwatch-s031","q":"How do you test a metric filter pattern?","a":"<p>Paste a real log entry into Test Pattern and confirm at least one row matches.</p>","hand":true},{"id":"cloudwatch-f0072","card":"q-cloudwatch-030-creating-a-metric-filter","sec":"cloudwatch-s031","q":"How do you get errors into the log streams in the demo app before creating a metric filter?","a":"<p>Use \"Fail all requests\" in the demo app to produce errors.</p>","hand":true},{"id":"cloudwatch-f0073","card":"q-cloudwatch-031-metric-details","sec":"cloudwatch-s032","q":"Which fields describe the metric a metric filter creates?","a":"<p>Filter name, metric name (for example <code>ValidationExceptions</code>), namespace (create or choose, for example <code>MetricFilters</code>), metric value, default value, unit and dimensions.</p>","hand":true},{"id":"cloudwatch-f0074","card":"q-cloudwatch-031-metric-details","sec":"cloudwatch-s032","q":"What does the metric value of a metric filter do?","a":"<p>It is the value added on each match. Use <code>1</code> to count occurrences, or another value (such as a duration) for other cases.</p>","hand":true},{"id":"cloudwatch-f0075","card":"q-cloudwatch-031-metric-details","sec":"cloudwatch-s032","q":"What does the default value of a metric filter do?","a":"<p>It is optional (for example <code>0</code>). If unset, nothing is pushed when no event matches, which is cheaper.</p>","hand":true},{"id":"cloudwatch-f0076","card":"q-cloudwatch-031-metric-details","sec":"cloudwatch-s032","q":"How do you check that a new metric filter works?","a":"<p>Review and create it, generate requests (for example 100), and look under Metrics &gt; namespace for the new metric.</p>","hand":true},{"id":"cloudwatch-f0077","card":"q-cloudwatch-032-metric-filter-guidance","sec":"cloudwatch-s033","q":"How does a metric filter behave, in programming terms?","a":"<p>It works like an <code>if</code> statement that adds to the metric on a match.</p>","hand":true},{"id":"cloudwatch-f0078","card":"q-cloudwatch-032-metric-filter-guidance","sec":"cloudwatch-s033","q":"What are the best practices for metric filters?","a":"<p>Test patterns with real log data. Use meaningful production names (<code>APIValidationErrors</code>) and group related metrics in one custom namespace.</p>","hand":true},{"id":"cloudwatch-f0079","card":"q-cloudwatch-032-metric-filter-guidance","sec":"cloudwatch-s033","q":"What can you do with a metric created from a metric filter?","a":"<p>Graph it on a dashboard, build alarms on it, and combine it with other CloudWatch metrics.</p>","hand":true},{"id":"cloudwatch-f0080","card":"q-cloudwatch-033-what-the-agent-does","sec":"cloudwatch-s034","q":"What does the CloudWatch agent collect, and where does it run?","a":"<p>System-level metrics and logs from EC2 instances and on-premise servers (hybrid or non-AWS environments), on Linux and Windows Server.</p>","hand":true},{"id":"cloudwatch-f0081","card":"q-cloudwatch-033-what-the-agent-does","sec":"cloudwatch-s034","q":"Which protocols does the CloudWatch agent support for custom application metrics?","a":"<p><strong>StatsD</strong> (Linux and Windows) and <strong>CollectD</strong> (Linux only).</p>","hand":true},{"id":"cloudwatch-f0082","card":"q-cloudwatch-034-install-and-configure-outline","sec":"cloudwatch-s035","q":"What are the steps to set up the CloudWatch agent?","a":"<ol>\n  <li>Install the agent on the target server.</li>\n  <li>Configure it for StatsD or CollectD by OS.</li>\n  <li>Specify which logs to collect.</li>\n  <li>Send data to CloudWatch for dashboards and analysis.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0083","card":"q-cloudwatch-034-install-and-configure-outline","sec":"cloudwatch-s035","q":"When do you choose StatsD or CollectD for the CloudWatch agent?","a":"<p>StatsD for cross-platform. CollectD for Linux-specific collection.</p>","hand":true},{"id":"cloudwatch-f0084","card":"q-cloudwatch-035-iam-role-for-the-agent","sec":"cloudwatch-s036","q":"Which three policies does the CloudWatch agent role need in the course, and why?","a":"<p><code>CloudWatchFullAccess</code> to send data. <code>EC2FullAccess</code> (or <code>AmazonEC2FullAccess</code>) to read instance metadata for EC2 dimensions. <code>AmazonSSMFullAccess</code> to store the configuration in SSM Parameter Store.</p>","hand":true},{"id":"cloudwatch-f0085","card":"q-cloudwatch-035-iam-role-for-the-agent","sec":"cloudwatch-s036","q":"How do you attach the agent role to an EC2 instance?","a":"<p>Create a role (for example <code>AgentDemo</code>), then EC2 &gt; Instances &gt; Actions &gt; Security &gt; Modify IAM role.</p>","hand":true},{"id":"cloudwatch-f0086","card":"q-cloudwatch-035-iam-role-for-the-agent","sec":"cloudwatch-s036","q":"What should you use in production instead of full-access policies for the CloudWatch agent?","a":"<p>Fine-grained permissions. <code>CloudWatchAgentServerPolicy</code> is the scoped option.</p>","hand":true},{"id":"cloudwatch-f0087","card":"q-cloudwatch-036-linux-setup-install","sec":"cloudwatch-s037","q":"How do you connect to the Linux instance and install the CloudWatch agent?","a":"<p>Connect with EC2 Instance Connect or SSH, then run:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo yum install amazon-cloudwatch-agent</code></pre></div>","hand":true},{"id":"cloudwatch-f0088","card":"q-cloudwatch-037-linux-setup-configuration-wizard","sec":"cloudwatch-s038","q":"Which command starts the CloudWatch agent configuration wizard on Linux?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-config-wizard</code></pre></div>","hand":true},{"id":"cloudwatch-f0089","card":"q-cloudwatch-037-linux-setup-configuration-wizard","sec":"cloudwatch-s038","q":"Which wizard answers does the Linux setup use for platform, StatsD and CollectD?","a":"<p>OS Linux, running on EC2, default user. StatsD yes, default port, collect interval 10 or 60 seconds. CollectD yes (needs its own install).</p>","hand":true},{"id":"cloudwatch-f0090","card":"q-cloudwatch-037-linux-setup-configuration-wizard","sec":"cloudwatch-s038","q":"Which wizard answers does the Linux setup use for metrics, resolution and logs?","a":"<p>Host and CPU metrics yes. EC2 dimensions yes, aggregate by instance ID. Resolution normal 60 seconds (high resolution costs more), default metric configuration. Monitor log files: no, when the app writes no local logs.</p>","hand":true},{"id":"cloudwatch-f0091","card":"q-cloudwatch-037-linux-setup-configuration-wizard","sec":"cloudwatch-s038","q":"How does the Linux wizard store the agent configuration?","a":"<p>In SSM Parameter Store, name <code>AmazonCloudWatch-linux</code>, confirm the region (for example <code>us-east-1</code>), and use the SDK option.</p>","hand":true},{"id":"cloudwatch-f0092","card":"q-cloudwatch-038-linux-setup-collectd-start-and-verify","sec":"cloudwatch-s039","q":"Which command installs CollectD on Linux?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo yum install collectd</code></pre></div>","hand":true},{"id":"cloudwatch-f0093","card":"q-cloudwatch-038-linux-setup-collectd-start-and-verify","sec":"cloudwatch-s039","q":"Which command starts the CloudWatch agent on EC2 using the configuration stored in SSM?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a fetch-config -m ec2 -c ssm:AmazonCloudWatch-linux -s</code></pre></div>\n<p>Replace <code>AmazonCloudWatch-linux</code> if you used another parameter name.</p>","hand":true},{"id":"cloudwatch-f0094","card":"q-cloudwatch-038-linux-setup-collectd-start-and-verify","sec":"cloudwatch-s039","q":"Which command shows the CloudWatch agent status on Linux?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a status</code></pre></div>","hand":true},{"id":"cloudwatch-f0095","card":"q-cloudwatch-038-linux-setup-collectd-start-and-verify","sec":"cloudwatch-s039","q":"Where do you look for agent metrics after a few minutes, and what do you check if none appear?","a":"<p>CloudWatch &gt; Metrics &gt; Custom namespaces &gt; <code>CWAgent</code>. Confirm the agent status, the attached IAM role, and that the config exists in Systems Manager &gt; Parameter Store.</p>","hand":true},{"id":"cloudwatch-f0096","card":"q-cloudwatch-039-windows-setup-connect-download-install","sec":"cloudwatch-s040","q":"How do you connect to a Windows Server EC2 instance for the CloudWatch agent setup?","a":"<p>Connect with RDP: download the RDP file and get the password with the key pair. Attach a role with the same three policies (for example <code>agentdemo</code>).</p>","hand":true},{"id":"cloudwatch-f0097","card":"q-cloudwatch-039-windows-setup-connect-download-install","sec":"cloudwatch-s040","q":"Which PowerShell commands download and install the CloudWatch agent on Windows?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">PowerShell</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Invoke-WebRequest -Uri https://s3.amazonaws.com/amazoncloudwatch-agent/windows/amd64/latest/amazon-cloudwatch-agent.msi -OutFile $env:USERPROFILE\\Downloads\\amazon-cloudwatch-agent.msi\nmsiexec /i $env:USERPROFILE\\Downloads\\amazon-cloudwatch-agent.msi</code></pre></div>","hand":true},{"id":"cloudwatch-f0098","card":"q-cloudwatch-040-windows-setup-wizard","sec":"cloudwatch-s041","q":"Which command starts the CloudWatch agent configuration wizard on Windows?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">PowerShell</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&amp; &quot;C:\\Program Files\\Amazon\\AmazonCloudWatchAgent\\amazon-cloudwatch-agent-config-wizard.exe&quot;</code></pre></div>","hand":true},{"id":"cloudwatch-f0099","card":"q-cloudwatch-040-windows-setup-wizard","sec":"cloudwatch-s041","q":"Which wizard answers does the Windows setup use for platform, StatsD and metrics?","a":"<p>OS auto-detected Windows, on EC2. StatsD yes with the default port and 60 second aggregation. No migration from an existing log agent. Host and per-core CPU metrics yes. EC2 dimensions yes (needs <code>AmazonEC2FullAccess</code>), aggregate by instance ID, standard 60 second resolution, basic configuration level.</p>","hand":true},{"id":"cloudwatch-f0100","card":"q-cloudwatch-040-windows-setup-wizard","sec":"cloudwatch-s041","q":"Which Windows Event Logs settings does the Windows wizard use?","a":"<p>Monitor yes, log group <code>system</code>, stream named by instance ID. Levels Information/Warning/Error/Critical (reduce for production), format XML, default retention. No additional log files.</p>","hand":true},{"id":"cloudwatch-f0101","card":"q-cloudwatch-040-windows-setup-wizard","sec":"cloudwatch-s041","q":"How does the Windows wizard store the configuration?","a":"<p>In SSM as <code>AmazonCloudWatch-windows</code>, verify the region, and use the SDK (instance role).</p>","hand":true},{"id":"cloudwatch-f0102","card":"q-cloudwatch-041-windows-setup-start-and-verify","sec":"cloudwatch-s042","q":"What do you check in Systems Manager before starting the agent on Windows?","a":"<p>Check Parameter Store for <code>AmazonCloudWatch-windows</code>. If it is missing, troubleshoot IAM permissions and region.</p>","hand":true},{"id":"cloudwatch-f0103","card":"q-cloudwatch-041-windows-setup-start-and-verify","sec":"cloudwatch-s042","q":"Which PowerShell command starts the CloudWatch agent on Windows using the SSM configuration?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">PowerShell</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>&amp; &quot;C:\\Program Files\\Amazon\\AmazonCloudWatchAgent\\amazon-cloudwatch-agent-ctl.ps1&quot; -a fetch-config -m ec2 -c ssm:AmazonCloudWatch-windows -s</code></pre></div>","hand":true},{"id":"cloudwatch-f0104","card":"q-cloudwatch-041-windows-setup-start-and-verify","sec":"cloudwatch-s042","q":"How do you check that the CloudWatch agent service runs on Windows?","a":"<p>Run the command below. The service should be <code>Running</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">PowerShell</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>Get-Service -Name AmazonCloudWatchAgent</code></pre></div>\n<p>Then check <code>CWAgent</code> metrics and the <code>system</code> log group.</p>","hand":true},{"id":"cloudwatch-f0105","card":"q-cloudwatch-041-windows-setup-start-and-verify","sec":"cloudwatch-s042","q":"Is CollectD supported on Windows, and how do you cut agent cost there?","a":"<p>CollectD is not supported on Windows. To cut cost, use standard resolution and limit event log levels.</p>","hand":true},{"id":"cloudwatch-f0106","card":"q-cloudwatch-042-what-it-is","sec":"cloudwatch-s043","q":"What is CloudWatch Metric Math?","a":"<p>It runs calculations across multiple metrics in real time and produces new time series.</p>","hand":true},{"id":"cloudwatch-f0107","card":"q-cloudwatch-042-what-it-is","sec":"cloudwatch-s043","q":"How do you add Metric Math to a graph, and what are the metric and expression IDs?","a":"<p>Metrics &gt; All metrics &gt; select metrics &gt; Graph metrics tab &gt; Add math. Each metric has an ID (M1, M2) and each expression has an ID (E1) that other expressions can reference.</p>","hand":true},{"id":"cloudwatch-f0108","card":"q-cloudwatch-042-what-it-is","sec":"cloudwatch-s043","q":"What do you do if a Metric Math graph shows no data?","a":"<p>Widen the timeframe (for example 4 weeks).</p>","hand":true},{"id":"cloudwatch-f0109","card":"q-cloudwatch-043-built-in-functions","sec":"cloudwatch-s044","q":"What does the Metric Math <code>RATE</code> function return?","a":"<p>The rate of change: the difference between the latest and previous data point. Switch aggregation from average to sum for totals over a period such as 5 minutes.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>RATE(M1)</code></pre></div>","hand":true},{"id":"cloudwatch-f0110","card":"q-cloudwatch-043-built-in-functions","sec":"cloudwatch-s044","q":"What does the Metric Math <code>DAY</code> function return, and how do you filter days with it?","a":"<p>The day of week, 1 (Monday) to 7 (Sunday). Combine it with <code>IF</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>IF(DAY(M1) &gt;= 6, M1)</code></pre></div>\n<p>This keeps only weekend values (6 Saturday, 7 Sunday).</p>","hand":true},{"id":"cloudwatch-f0111","card":"q-cloudwatch-043-built-in-functions","sec":"cloudwatch-s044","q":"What does the Metric Math <code>FILL</code> function do?","a":"<p>It replaces missing data points so intermittent line graphs read as continuous.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>FILL(M1, 0)</code></pre></div>\n<p>This fills gaps in the error series with 0.</p>","hand":true},{"id":"cloudwatch-f0112","card":"q-cloudwatch-044-practical-tips","sec":"cloudwatch-s045","q":"Why replace <code>METRICS()</code> with specific IDs such as <code>M1</code> in a Metric Math expression?","a":"<p>So the expression does not aggregate everything selected. Use the edit button to do it.</p>","hand":true},{"id":"cloudwatch-f0113","card":"q-cloudwatch-044-practical-tips","sec":"cloudwatch-s045","q":"What do you do when several metrics (errors, invocations) are selected in Metric Math?","a":"<p>Point the expression at specific IDs.</p>","hand":true},{"id":"cloudwatch-f0114","card":"q-cloudwatch-044-practical-tips","sec":"cloudwatch-s045","q":"How do you zoom a CloudWatch metrics graph and go back?","a":"<p>Zoom in on the graph and reset zoom for the full range.</p>","hand":true},{"id":"cloudwatch-f0115","card":"q-cloudwatch-045-custom-expressions","sec":"cloudwatch-s046","q":"How do you start a custom Metric Math expression, and which metrics does the Lambda example use?","a":"<p>Add math &gt; Start with an empty expression. M1 = Errors, M2 = Invocations, M3 = Duration for the Lambda function.</p>","hand":true},{"id":"cloudwatch-f0116","card":"q-cloudwatch-045-custom-expressions","sec":"cloudwatch-s046","q":"Which Metric Math expression gives the average duration per invocation?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>M3 / M2</code></pre></div>\n<p>It returns milliseconds.</p>","hand":true},{"id":"cloudwatch-f0117","card":"q-cloudwatch-045-custom-expressions","sec":"cloudwatch-s046","q":"Which Metric Math expression gives the error rate percentage, and what are example values?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>(M1 / M2) * 100</code></pre></div>\n<p>It gives 33% for one failure in three and 100% when every request fails. Name it \"Error Rate\" (ID E1).</p>","hand":true},{"id":"cloudwatch-f0118","card":"q-cloudwatch-045-custom-expressions","sec":"cloudwatch-s046","q":"What does the Metric Math expression <code>IF(E1 &gt;= 25, E1, 0)</code> do?","a":"<p>It shows only error rates of 25% or more and sets the rest to 0. <code>IF</code> must be upper case. Raise the threshold (for example to 75) for a stricter filter.</p>","hand":true},{"id":"cloudwatch-f0119","card":"q-cloudwatch-045-custom-expressions","sec":"cloudwatch-s046","q":"How do you see only the expression result on a Metric Math graph?","a":"<p>Untick the other metrics.</p>","hand":true},{"id":"cloudwatch-f0120","card":"q-cloudwatch-046-why-dashboards","sec":"cloudwatch-s047","q":"Why use a CloudWatch dashboard instead of the metrics console graph?","a":"<p>Graphs built in the metrics console are not saved if you close the browser or change device. A dashboard keeps them.</p>","hand":true},{"id":"cloudwatch-f0121","card":"q-cloudwatch-047-adding-a-graph-to-a-dashboard","sec":"cloudwatch-s048","q":"Which widget types can a CloudWatch dashboard have?","a":"<p>Line graph, alarm status, text and logs. Use Line for time series.</p>","hand":true},{"id":"cloudwatch-f0122","card":"q-cloudwatch-047-adding-a-graph-to-a-dashboard","sec":"cloudwatch-s048","q":"What are the two ways to add a graph to a CloudWatch dashboard?","a":"<p>Option 1: build the metrics and math inside the widget. Option 2: from an existing graph choose Actions &gt; Add to dashboard, pick the dashboard and widget type (Line), give a title and add it.</p>","hand":true},{"id":"cloudwatch-f0123","card":"q-cloudwatch-047-adding-a-graph-to-a-dashboard","sec":"cloudwatch-s048","q":"What must you do after adding widgets to a dashboard?","a":"<p>Save the dashboard to persist it.</p>","hand":true},{"id":"cloudwatch-f0124","card":"q-cloudwatch-048-what-an-alarm-does","sec":"cloudwatch-s049","q":"What does a CloudWatch alarm do?","a":"<p>It watches a metric against a threshold and triggers actions or notifications, so nobody has to check the console by hand. It can be set on any metric.</p>","hand":true},{"id":"cloudwatch-f0125","card":"q-cloudwatch-048-what-an-alarm-does","sec":"cloudwatch-s049","q":"Besides notifications, what actions can a CloudWatch alarm take?","a":"<p>It can shut down unused resources, or scale an EC2 Auto Scaling group (add instances above a CPU threshold, remove them below). This keeps performance and cost balanced.</p>","hand":true},{"id":"cloudwatch-f0126","card":"q-cloudwatch-049-alarm-states","sec":"cloudwatch-s050","q":"What are the three CloudWatch alarm states?","a":"<p><code>INSUFFICIENT_DATA</code>: initial state until enough data is collected. <code>OK</code>: metric within threshold. <code>ALARM</code>: threshold breached, actions fire.</p>","hand":true},{"id":"cloudwatch-f0127","card":"q-cloudwatch-049-alarm-states","sec":"cloudwatch-s050","q":"Why configure notifications for both Alarm and OK states?","a":"<p>Administrators learn when an issue starts and when it is resolved, which avoids duplicated work.</p>","hand":true},{"id":"cloudwatch-f0128","card":"q-cloudwatch-050-alarm-on-lambda-errors-console-steps","sec":"cloudwatch-s051","q":"What are the console steps to set up an alarm on Lambda errors?","a":"<ol>\n  <li>Generate baseline requests (for example 100).</li>\n  <li>CloudWatch &gt; Alarms &gt; All alarms &gt; Create alarm.</li>\n  <li>Select metric: Lambda &gt; By Function Name &gt; the function &gt; <code>Errors</code>.</li>\n  <li>Change the statistic to Sum and the period to 1 minute.</li>\n  <li>Choose a Static threshold.</li>\n  <li>Create an SNS topic notification.</li>\n  <li>Name and create the alarm.</li>\n  <li>Test it.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0129","card":"q-cloudwatch-050-alarm-on-lambda-errors-console-steps","sec":"cloudwatch-s051","q":"Why change the Lambda errors alarm statistic from Average to Sum and the period to 1 minute?","a":"<p>Sum counts errors, and a 1 minute period triggers faster.</p>","hand":true},{"id":"cloudwatch-f0130","card":"q-cloudwatch-050-alarm-on-lambda-errors-console-steps","sec":"cloudwatch-s051","q":"Which threshold type and value does the Lambda errors alarm use, and why 20?","a":"<p>A <strong>Static</strong> threshold (over Anomaly Detection): errors greater than 20 in 1 minute. The API sends about one request a second, so roughly 20 failures a minute is the failure rate.</p>","hand":true},{"id":"cloudwatch-f0131","card":"q-cloudwatch-050-alarm-on-lambda-errors-console-steps","sec":"cloudwatch-s051","q":"How is the SNS notification set up for the Lambda errors alarm?","a":"<p>Create an SNS topic (for example <code>apiadmins</code>) with comma-separated email addresses, for both Alarm and OK states.</p>","hand":true},{"id":"cloudwatch-f0132","card":"q-cloudwatch-050-alarm-on-lambda-errors-console-steps","sec":"cloudwatch-s051","q":"How do you test the Lambda errors alarm and which state changes do you see?","a":"<p>Tick \"Fail all requests\". The alarm starts at Insufficient Data, then moves to OK and to Alarm, and each change sends a notification. When the issue is fixed it returns to OK.</p>","hand":true},{"id":"cloudwatch-f0133","card":"q-cloudwatch-051-alarm-on-lambda-errors-boto3","sec":"cloudwatch-s052","q":"Which boto3 call creates the alarm that fires when Lambda errors exceed 20 per minute?","a":"<p><code>put_metric_alarm</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>cloudwatch.put_metric_alarm(\n    AlarmName=&#x27;apiadmins&#x27;,\n    ComparisonOperator=&#x27;GreaterThanThreshold&#x27;,\n    EvaluationPeriods=1,\n    MetricName=&#x27;Errors&#x27;,\n    Namespace=&#x27;AWS/Lambda&#x27;,\n    Period=60,\n    Statistic=&#x27;Sum&#x27;,\n    Threshold=20.0,</code></pre></div>","hand":true},{"id":"cloudwatch-f0134","card":"q-cloudwatch-051-alarm-on-lambda-errors-boto3","sec":"cloudwatch-s052","q":"Which parameters send the Lambda errors alarm to SNS on both ALARM and OK?","a":"<p><code>AlarmActions</code> and <code>OKActions</code> with the SNS topic ARN:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>AlarmActions=[&#x27;arn:aws:sns:us-east-1:123456789012:apiadmins&#x27;],\nOKActions=[&#x27;arn:aws:sns:us-east-1:123456789012:apiadmins&#x27;],</code></pre></div>","hand":true},{"id":"cloudwatch-f0135","card":"q-cloudwatch-051-alarm-on-lambda-errors-boto3","sec":"cloudwatch-s052","q":"What are the guidelines for alarms that count errors?","a":"<p>Use Sum (not Average) to count errors, short evaluation periods for quick detection, and test alarms by simulating failures.</p>","hand":true},{"id":"cloudwatch-f0136","card":"q-cloudwatch-052-alarm-that-notifies-through-sns-on-high","sec":"cloudwatch-s053","q":"Which boto3 alarm notifies through SNS when CPU stays above 70% for 10 minutes?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>cloudwatch.put_metric_alarm(\n    AlarmName=&#x27;HighCPUUtilization&#x27;,\n    ComparisonOperator=&#x27;GreaterThanThreshold&#x27;,\n    EvaluationPeriods=2,\n    MetricName=&#x27;CPUUtilization&#x27;,\n    Namespace=&#x27;AWS/EC2&#x27;,\n    Period=300,\n    Statistic=&#x27;Average&#x27;,\n    Threshold=70.0,</code></pre></div>","hand":true},{"id":"cloudwatch-f0137","card":"q-cloudwatch-052-alarm-that-notifies-through-sns-on-high","sec":"cloudwatch-s053","q":"Why does the high CPU alarm use <code>EvaluationPeriods=2</code> with <code>Period=300</code>?","a":"<p>Two 5-minute periods above 70% means 10 minutes of sustained load.</p>","hand":true},{"id":"cloudwatch-f0138","card":"q-cloudwatch-052-alarm-that-notifies-through-sns-on-high","sec":"cloudwatch-s053","q":"What are the common actions for a CloudWatch alarm?","a":"<p>SNS notifications and Auto Scaling policies.</p>","hand":true},{"id":"cloudwatch-f0139","card":"q-cloudwatch-053-alarm-actions-with-auto-scaling-create-t","sec":"cloudwatch-s054","q":"How do you create the Auto Scaling group used for the alarm demo?","a":"<p>EC2 &gt; Auto Scaling Groups &gt; Create. Name <code>scalingdemo</code>. Create a launch template (<code>simplegroup</code>: Amazon Linux, an instance type such as t2.micro, a key pair, default VPC and subnet, auto-assign public IP).</p>","hand":true},{"id":"cloudwatch-f0140","card":"q-cloudwatch-053-alarm-actions-with-auto-scaling-create-t","sec":"cloudwatch-s054","q":"Which capacity settings does the <code>scalingdemo</code> group use, and why must the maximum exceed 1?","a":"<p>Minimum 1, maximum 2, desired 1. The maximum must be above 1 or scaling cannot add an instance.</p>","hand":true},{"id":"cloudwatch-f0141","card":"q-cloudwatch-054-alarm-actions-with-auto-scaling-policies","sec":"cloudwatch-s055","q":"Which scaling policies does the <code>scalingdemo</code> group use?","a":"<p>Type Simple scaling dynamic policies. <code>ScaleUp</code> adds 1 capacity unit, cooldown 300 seconds. <code>ScaleDown</code> removes 1 capacity unit, cooldown 300 seconds.</p>","hand":true},{"id":"cloudwatch-f0142","card":"q-cloudwatch-054-alarm-actions-with-auto-scaling-policies","sec":"cloudwatch-s055","q":"What does the cooldown on a scaling policy do?","a":"<p>It prevents rapid repeated scaling.</p>","hand":true},{"id":"cloudwatch-f0143","card":"q-cloudwatch-054-alarm-actions-with-auto-scaling-policies","sec":"cloudwatch-s055","q":"How is the <code>ScaleUpDown</code> alarm configured in the console?","a":"<p>CloudWatch &gt; Alarms &gt; Create alarm on EC2 &gt; By Auto Scaling Group &gt; <code>scalingdemo</code> &gt; <code>CPUUtilization</code>, Average, 1 minute, static threshold greater than 70. Alarm state runs <code>ScaleUp</code> on <code>scalingdemo</code>. OK state runs <code>ScaleDown</code>. A notification is optional.</p>","hand":true},{"id":"cloudwatch-f0144","card":"q-cloudwatch-054-alarm-actions-with-auto-scaling-policies","sec":"cloudwatch-s055","q":"Which parameters wire the <code>ScaleUpDown</code> alarm to the scaling policies in boto3?","a":"<p><code>AlarmActions</code> points to the scale-up policy and <code>OKActions</code> to the scale-down policy:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>AlarmActions=[&#x27;arn:aws:autoscaling:us-east-1:123456789012:scalingPolicy:policy-id:scale-up&#x27;],\nOKActions=[&#x27;arn:aws:autoscaling:us-east-1:123456789012:scalingPolicy:policy-id:scale-down&#x27;],\nDimensions=[{&#x27;Name&#x27;: &#x27;AutoScalingGroupName&#x27;, &#x27;Value&#x27;: &#x27;scalingdemo&#x27;}]</code></pre></div>","hand":true},{"id":"cloudwatch-f0145","card":"q-cloudwatch-055-alarm-actions-with-auto-scaling-test-wit","sec":"cloudwatch-s056","q":"Which commands generate CPU load on a group instance to test the scaling alarm?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo yum install -y stress-ng\nstress-ng --cpu 4 --timeout 60s</code></pre></div>\n<p>Connect with EC2 Instance Connect first.</p>","hand":true},{"id":"cloudwatch-f0146","card":"q-cloudwatch-055-alarm-actions-with-auto-scaling-test-wit","sec":"cloudwatch-s056","q":"What happens during the stress-ng scaling test?","a":"<p>CPU rises from about 37% to above 70%, the alarm goes to In alarm and <code>ScaleUp</code> adds an instance. About a minute after the load stops, CPU falls, the alarm returns to OK and <code>ScaleDown</code> removes one.</p>","hand":true},{"id":"cloudwatch-f0147","card":"q-cloudwatch-055-alarm-actions-with-auto-scaling-test-wit","sec":"cloudwatch-s056","q":"How do you confirm the Auto Scaling test worked, and what if CPU does not cross the threshold?","a":"<p>Under Auto Scaling group &gt; Instance management, confirm the count went to 2 then back to 1. Adjust stress parameters if CPU does not cross the threshold.</p>","hand":true},{"id":"cloudwatch-f0148","card":"q-cloudwatch-056-alarm-on-rum-javascript-errors","sec":"cloudwatch-s057","q":"How do you set up an alarm on RUM JavaScript errors?","a":"<p>In the app monitor, Configuration &gt; Alarms &gt; Create a new alarm. Namespace <code>AWS/RUM</code>, filter by Application Name (<code>demoapp</code>), metric <code>JsErrorCount</code>, statistic Sum, period 1 minute, condition greater than 5. Notify an existing SNS topic and name it (<code>rumdemo</code>).</p>","hand":true},{"id":"cloudwatch-f0149","card":"q-cloudwatch-056-alarm-on-rum-javascript-errors","sec":"cloudwatch-s057","q":"How do you test the RUM JavaScript errors alarm?","a":"<p>Start 100 requests and wait 1-2 minutes for In alarm. The demo produces about 9 errors a minute.</p>","hand":true},{"id":"cloudwatch-f0150","card":"q-cloudwatch-056-alarm-on-rum-javascript-errors","sec":"cloudwatch-s057","q":"Why might the RUM alarm stay at Insufficient Data, and what do you do?","a":"<p>RUM may be ignoring repeated <code>localhost</code> sessions. Open the app in an incognito window, open DevTools &gt; Network, restart the requests, and confirm calls reach the app monitor:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Plaintext</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>https://&lt;aws-rum-endpoint&gt;/appmonitor/&lt;app-monitor-id&gt;</code></pre></div>","hand":true},{"id":"cloudwatch-f0151","card":"q-cloudwatch-057-what-synthetics-does","sec":"cloudwatch-s058","q":"What is CloudWatch Synthetics?","a":"<p>It monitors sites, API endpoints and web workflows from the outside by simulating real customer actions, without real customer traffic. It finds problems before customers do.</p>","hand":true},{"id":"cloudwatch-f0152","card":"q-cloudwatch-057-what-synthetics-does","sec":"cloudwatch-s058","q":"What does CloudWatch Synthetics check?","a":"<p>That containers, microservices, serverless functions and third-party services work together. It checks availability and latency of endpoints and the consistency of site content.</p>","hand":true},{"id":"cloudwatch-f0153","card":"q-cloudwatch-057-what-synthetics-does","sec":"cloudwatch-s058","q":"What is a canary, and how often can it run?","a":"<p>A configurable script that mimics customer actions. It runs once or on a schedule, as often as once per minute, 24/7.</p>","hand":true},{"id":"cloudwatch-f0154","card":"q-cloudwatch-057-what-synthetics-does","sec":"cloudwatch-s058","q":"How do you get notified about canary problems?","a":"<p>Alarms on canary metrics send notifications.</p>","hand":true},{"id":"cloudwatch-f0155","card":"q-cloudwatch-058-basic-api-health-canary-script","sec":"cloudwatch-s059","q":"How does a basic API health canary call an endpoint with Synthetics?","a":"<p>It uses <code>executeHttpStep</code> with request options:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>let response = await synthetics.executeHttpStep(&#x27;Check API Health&#x27;, requestOptions);\nlog.info(&quot;API Response Status: &quot; + response.statusCode);</code></pre></div>","hand":true},{"id":"cloudwatch-f0156","card":"q-cloudwatch-058-basic-api-health-canary-script","sec":"cloudwatch-s059","q":"How does the basic canary script fail the run when the API is unhealthy?","a":"<p>It throws an error when the status is not 200:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if (response.statusCode !== 200) {\n    throw new Error(&quot;API health check failed!&quot;);\n}</code></pre></div>","hand":true},{"id":"cloudwatch-f0157","card":"q-cloudwatch-058-basic-api-health-canary-script","sec":"cloudwatch-s059","q":"Which request options does the basic API health canary use?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>hostname: &#x27;api.example.com&#x27;,\nmethod: &#x27;GET&#x27;,\npath: &#x27;/health&#x27;,\nprotocol: &#x27;https:&#x27;</code></pre></div>","hand":true},{"id":"cloudwatch-f0158","card":"q-cloudwatch-059-alarm-on-canary-success-rate","sec":"cloudwatch-s060","q":"Which AWS CLI command alarms when a canary's success percentage drops below 90?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch put-metric-alarm \\\n    --alarm-name CanaryFailureAlarm \\\n    --metric-name SuccessPercent \\\n    --namespace AWS/Synthetics \\\n    --threshold 90.0 \\\n    --comparison-operator LessThanThreshold \\\n    --evaluation-periods 1 \\\n    --period 60 \\\n    --statistic Average \\\n    --alarm-actions arn:aws:sns:region:account-id:my-sns-topic</code></pre></div>","hand":true},{"id":"cloudwatch-f0159","card":"q-cloudwatch-060-creating-a-heartbeat-canary","sec":"cloudwatch-s061","q":"Where do you create a canary, and what are the creation methods?","a":"<p>CloudWatch &gt; Application monitoring &gt; Synthetics Canaries &gt; Create canary. Blueprint: predefined templates (heartbeat monitoring) for beginners. Inline editor: write a custom script. Import from S3: reuse a script stored in S3.</p>","hand":true},{"id":"cloudwatch-f0160","card":"q-cloudwatch-060-creating-a-heartbeat-canary","sec":"cloudwatch-s061","q":"Which settings does the heartbeat blueprint ask for?","a":"<p>A name, the endpoint URL (remove stray parts such as <code>#</code>), optional additional endpoints, screenshots (on by default) and a schedule (continuous, a cron expression, or run once).</p>","hand":true},{"id":"cloudwatch-f0161","card":"q-cloudwatch-060-creating-a-heartbeat-canary","sec":"cloudwatch-s061","q":"What does the heartbeat blueprint script look like?","a":"<p>The same pattern as the basic API canary, with <code>executeHttpStep('Check Page Load', ...)</code> against <code>/</code>.</p>","hand":true},{"id":"cloudwatch-f0162","card":"q-cloudwatch-061-reading-canary-results","sec":"cloudwatch-s062","q":"What does the canary home page show?","a":"<p>The list of canaries and the last run status (passed or failed).</p>","hand":true},{"id":"cloudwatch-f0163","card":"q-cloudwatch-061-reading-canary-results","sec":"cloudwatch-s062","q":"What do you get for each canary run?","a":"<p>The executed steps, screenshots of the app, logs for debugging, and a HAR file.</p>","hand":true},{"id":"cloudwatch-f0164","card":"q-cloudwatch-061-reading-canary-results","sec":"cloudwatch-s062","q":"What is a HAR file in a canary run?","a":"<p>A record of the network requests made during the page load (like the browser Network tab). It is useful for spotting slow components.</p>","hand":true},{"id":"cloudwatch-f0165","card":"q-cloudwatch-062-api-canary-with-two-steps","sec":"cloudwatch-s063","q":"How do you create an API canary for an API Gateway API?","a":"<p>Create canary &gt; blueprint <strong>API Canary</strong>, name <code>serverlessapi</code>. Choose \"I'm using Amazon API Gateway\", pick the API (<code>cloudwatchapi</code>) and stage (<code>Production</code>); the hostname fills in.</p>","hand":true},{"id":"cloudwatch-f0166","card":"q-cloudwatch-062-api-canary-with-two-steps","sec":"cloudwatch-s063","q":"Which two HTTP requests does the two-step API canary add?","a":"<ol>\n  <li><code>Create new item</code>: POST to the base URL with a JSON payload (<code>id</code>, <code>name</code>).</li>\n  <li><code>Get created item</code>: GET by id, path such as <code>/production/5</code>.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0167","card":"q-cloudwatch-062-api-canary-with-two-steps","sec":"cloudwatch-s063","q":"Why untick \"Continue if step fails\" on the POST step of the API canary?","a":"<p>So the run stops if the POST fails.</p>","hand":true},{"id":"cloudwatch-f0168","card":"q-cloudwatch-063-api-canary-with-a-random-payload","sec":"cloudwatch-s064","q":"How does the API canary script generate a random payload?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>function generateRandomPayload() {\n    const randomId = Math.floor(Math.random() * 10000);\n    return { id: randomId, name: `canary-demo-${randomId}` };\n}</code></pre></div>","hand":true},{"id":"cloudwatch-f0169","card":"q-cloudwatch-063-api-canary-with-a-random-payload","sec":"cloudwatch-s064","q":"How does the random payload canary reuse the id in the GET step?","a":"<p>It puts <code>randomPayload.id</code> in the GET path:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>path: `/production/${randomPayload.id}`,</code></pre></div>","hand":true},{"id":"cloudwatch-f0170","card":"q-cloudwatch-063-api-canary-with-a-random-payload","sec":"cloudwatch-s064","q":"How does the random payload canary name its two steps and fail on error?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>let response1 = await synthetics.executeHttpStep(&#x27;Create new item&#x27;, requestOptionsStep1);\nlet response2 = await synthetics.executeHttpStep(&#x27;Get created item&#x27;, requestOptionsStep2);</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>throw new Error(&quot;Create item failed!&quot;);</code></pre></div>","hand":true},{"id":"cloudwatch-f0171","card":"q-cloudwatch-064-logging-request-and-response-bodies","sec":"cloudwatch-s065","q":"Are request and response bodies logged by Synthetics canaries by default?","a":"<p>No. By default bodies are not logged.</p>","hand":true},{"id":"cloudwatch-f0172","card":"q-cloudwatch-064-logging-request-and-response-bodies","sec":"cloudwatch-s065","q":"How do you make a canary log request and response bodies?","a":"<p>Actions &gt; Edit &gt; Script editor, and set these in each step's options:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>config: {\n    includeRequestHeaders: true,\n    includeRequestBody: true,\n    includeResponseBody: true\n}</code></pre></div>","hand":true},{"id":"cloudwatch-f0173","card":"q-cloudwatch-064-logging-request-and-response-bodies","sec":"cloudwatch-s065","q":"Why use random payloads in canaries, and where do you see the id?","a":"<p>Random payloads give more realistic test coverage. After the next run the logs show the bodies and the random id (for example <code>5431</code>).</p>","hand":true},{"id":"cloudwatch-f0174","card":"q-cloudwatch-065-canary-recorder-plugin","sec":"cloudwatch-s066","q":"What is the CloudWatch Synthetics Recorder?","a":"<p>A browser extension that records user flows (click, log in, type) and generates the script, so you do not write it by hand.</p>","hand":true},{"id":"cloudwatch-f0175","card":"q-cloudwatch-065-canary-recorder-plugin","sec":"cloudwatch-s066","q":"What are the steps to use the canary recorder?","a":"<ol>\n  <li>Create canary &gt; Canary Recorder &gt; install the Chrome extension.</li>\n  <li>Open the target app, click Start recording, perform the actions, click End recording, and copy the script.</li>\n  <li>Name the canary and paste or upload the script.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0176","card":"q-cloudwatch-065-canary-recorder-plugin","sec":"cloudwatch-s066","q":"What are the limits of scripts from the canary recorder?","a":"<p>The app URL is hardcoded and default step names are generic.</p>","hand":true},{"id":"cloudwatch-f0177","card":"q-cloudwatch-066-recorded-script-and-step-naming","sec":"cloudwatch-s067","q":"How does a recorded canary script enable screenshots on steps?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>syntheticsConfiguration.setConfig({\n    screenshotOnStepSuccess: true,\n    screenshotOnStepFailure: true\n});</code></pre></div>","hand":true},{"id":"cloudwatch-f0178","card":"q-cloudwatch-066-recorded-script-and-step-naming","sec":"cloudwatch-s067","q":"How does a recorded canary script run a browser action as a named step?","a":"<p>It gets a page and uses <code>executeStep</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>let page = await synthetics.getPage();\nawait synthetics.executeStep(&#x27;Navigate to scorekeep&#x27;, async function () {\n    await page.goto(&#x27;https://scorekeep.example.com&#x27;, { waitUntil: &#x27;domcontentloaded&#x27; });\n});</code></pre></div>","hand":true},{"id":"cloudwatch-f0179","card":"q-cloudwatch-066-recorded-script-and-step-naming","sec":"cloudwatch-s067","q":"Why rename generic canary steps such as <code>step_1</code>?","a":"<p>Descriptive names (<code>Set user to Canary</code>) make results readable.</p>","hand":true},{"id":"cloudwatch-f0180","card":"q-cloudwatch-067-what-x-ray-gives-you","sec":"cloudwatch-s068","q":"What is AWS X-Ray used for?","a":"<p>End-to-end visibility by tracing requests across distributed systems.</p>","hand":true},{"id":"cloudwatch-f0181","card":"q-cloudwatch-067-what-x-ray-gives-you","sec":"cloudwatch-s068","q":"What do distributed tracing and the dynamic service map in X-Ray show?","a":"<p>Distributed tracing follows the entire request lifecycle, including AWS services and external resources. The dynamic service map draws components and their interactions, showing dependencies and architecture.</p>","hand":true},{"id":"cloudwatch-f0182","card":"q-cloudwatch-067-what-x-ray-gives-you","sec":"cloudwatch-s068","q":"Which performance metrics and root cause features does X-Ray give?","a":"<p>Request latency, request rate, errors and fault rates. Root cause analysis correlates traces and logs to show which service failed and why.</p>","hand":true},{"id":"cloudwatch-f0183","card":"q-cloudwatch-067-what-x-ray-gives-you","sec":"cloudwatch-s068","q":"Which services does X-Ray integrate with?","a":"<p>Lambda, EC2, ECS, API Gateway and others, across service boundaries.</p>","hand":true},{"id":"cloudwatch-f0184","card":"q-cloudwatch-068-instrumenting-python-code","sec":"cloudwatch-s069","q":"How do you add X-Ray to a Flask app in Python?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from aws_xray_sdk.core import xray_recorder\nfrom aws_xray_sdk.ext.flask import XRay\napp = Flask(__name__)\nXRay(app)</code></pre></div>","hand":true},{"id":"cloudwatch-f0185","card":"q-cloudwatch-068-instrumenting-python-code","sec":"cloudwatch-s069","q":"Which X-Ray decorator traces a Python function?","a":"<p><code>@xray_recorder.capture</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>@xray_recorder.capture(&#x27;my_lambda_function&#x27;)\ndef lambda_handler(event, context):</code></pre></div>","hand":true},{"id":"cloudwatch-f0186","card":"q-cloudwatch-068-instrumenting-python-code","sec":"cloudwatch-s069","q":"How do you create a subsegment and record an exception with the X-Ray SDK in Python?","a":"<p><code>begin_subsegment</code>, <code>record_exception</code> and <code>end_subsegment</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>subsegment = xray_recorder.begin_subsegment(&#x27;api_call&#x27;)\nxray_recorder.record_exception(e)\nxray_recorder.end_subsegment()</code></pre></div>","hand":true},{"id":"cloudwatch-f0187","card":"q-cloudwatch-069-demo-app-with-cloudformation","sec":"cloudwatch-s070","q":"How do you deploy the X-Ray demo app?","a":"<p>In the CloudWatch console go to X-Ray Traces &gt; Service Map &gt; Set up demo app &gt; Create sample application with CloudFormation. Stack name <code>X-Ray-demo-app</code>, accept defaults, acknowledge resource creation.</p>","hand":true},{"id":"cloudwatch-f0188","card":"q-cloudwatch-069-demo-app-with-cloudformation","sec":"cloudwatch-s070","q":"How do you reach the Scorekeep demo app and create traffic?","a":"<p>When the stack finishes, open the URL in its Outputs tab. Set a username, create a session, create a game (for example <code>demo</code>, <code>tic-tac-toe</code>) and play to generate backend requests.</p>","hand":true},{"id":"cloudwatch-f0189","card":"q-cloudwatch-070-enabling-tracing-in-a-lambda-template","sec":"cloudwatch-s071","q":"Which CloudFormation property turns on X-Ray tracing for a Lambda function?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>TracingConfig:\n  Mode: Active</code></pre></div>","hand":true},{"id":"cloudwatch-f0190","card":"q-cloudwatch-070-enabling-tracing-in-a-lambda-template","sec":"cloudwatch-s071","q":"Which managed policies does the Lambda role in the tracing template use?","a":"<p><code>AWSXRayDaemonWriteAccess</code> and <code>AWSLambdaBasicExecutionRole</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">YAML</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>- arn:aws:iam::aws:policy/AWSXRayDaemonWriteAccess\n- arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole</code></pre></div>","hand":true},{"id":"cloudwatch-f0191","card":"q-cloudwatch-071-reading-the-service-map","sec":"cloudwatch-s072","q":"What do nodes and edges mean in the X-Ray service map?","a":"<p>Nodes are services and edges are interactions.</p>","hand":true},{"id":"cloudwatch-f0192","card":"q-cloudwatch-071-reading-the-service-map","sec":"cloudwatch-s072","q":"What does the Scorekeep service map contain?","a":"<p>The client, an ECS container, an SNS topic for real-time updates, and DynamoDB tables <code>game</code>, <code>session</code>, <code>state</code> and <code>user</code>.</p>","hand":true},{"id":"cloudwatch-f0193","card":"q-cloudwatch-071-reading-the-service-map","sec":"cloudwatch-s072","q":"What do the circle colors around an X-Ray service map node mean?","a":"<p>Yellow for slow requests and red for failed requests (50% red when half fail).</p>","hand":true},{"id":"cloudwatch-f0194","card":"q-cloudwatch-071-reading-the-service-map","sec":"cloudwatch-s072","q":"How do you get response time metrics for a node in the service map?","a":"<p>Click the node (for example the ECS container). Zoom with the scroll wheel or buttons.</p>","hand":true},{"id":"cloudwatch-f0195","card":"q-cloudwatch-072-reading-traces","sec":"cloudwatch-s073","q":"How can you find traces in X-Ray?","a":"<p>Filter by trace ID, by node (<code>service id name: \"Scorekeep\", type: client</code>), or click a node in the service map &gt; View traces. Adjust the time range (for example last 15 minutes).</p>","hand":true},{"id":"cloudwatch-f0196","card":"q-cloudwatch-072-reading-traces","sec":"cloudwatch-s073","q":"What do the trace map and timeline show in an X-Ray trace?","a":"<p>The trace map shows the flow, such as Client to ECS container to DynamoDB <code>game</code> and <code>session</code> tables. The timeline shows how long each step took and where requests slow down or fail.</p>","hand":true},{"id":"cloudwatch-f0197","card":"q-cloudwatch-073-tracing-dynamodb-calls-through-boto3","sec":"cloudwatch-s074","q":"What does <code>patch_all()</code> do in the X-Ray SDK for Python?","a":"<p>It makes boto3 calls show up as subsegments in the service map.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from aws_xray_sdk.ext.boto import patch_all\npatch_all()</code></pre></div>","hand":true},{"id":"cloudwatch-f0198","card":"q-cloudwatch-073-tracing-dynamodb-calls-through-boto3","sec":"cloudwatch-s074","q":"How does the traced Lambda read a DynamoDB item in the X-Ray demo?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>dynamodb = boto3.client(&#x27;dynamodb&#x27;)\nresponse = dynamodb.get_item(\n    TableName=&#x27;game&#x27;,\n    Key={&#x27;game_id&#x27;: {&#x27;S&#x27;: event.get(&#x27;game_id&#x27;, &#x27;demo&#x27;)}}\n)</code></pre></div>","hand":true},{"id":"cloudwatch-f0199","card":"q-cloudwatch-074-x-ray-with-api-gateway-and-lambda","sec":"cloudwatch-s075","q":"How do you enable X-Ray tracing for API Gateway and Lambda?","a":"<p>API Gateway console &gt; the API &gt; Stages &gt; <code>production</code> &gt; Logs and Tracing &gt; enable <strong>X-Ray Tracing</strong>, save. Lambda console &gt; the function &gt; Configuration &gt; Monitoring and operations tools &gt; Edit &gt; enable <strong>Active tracing</strong>, save.</p>","hand":true},{"id":"cloudwatch-f0200","card":"q-cloudwatch-074-x-ray-with-api-gateway-and-lambda","sec":"cloudwatch-s075","q":"What does the service map show for the API Gateway and Lambda demo?","a":"<p>Client to API Gateway (<code>production</code> stage) to Lambda. API Gateway has a red circle (about 35% of requests fail with 502). Lambda has a yellow circle (400 errors for invalid payloads).</p>","hand":true},{"id":"cloudwatch-f0201","card":"q-cloudwatch-074-x-ray-with-api-gateway-and-lambda","sec":"cloudwatch-s075","q":"How do you find the root cause of a failed 502 in the X-Ray API Gateway demo?","a":"<p>Select the API &gt; View traces, open a failed 502 trace. The flow ends at Lambda returning a non-OK status. Exceptions shows \"One or more parameter values were invalid, missing the key ID in the item\". Fix the missing key in the payload.</p>","hand":true},{"id":"cloudwatch-f0202","card":"q-cloudwatch-074-x-ray-with-api-gateway-and-lambda","sec":"cloudwatch-s075","q":"How do you send traffic for the X-Ray API Gateway demo?","a":"<p>Send 1,000 requests, one failure in three, with the API tester.</p>","hand":true},{"id":"cloudwatch-f0203","card":"q-cloudwatch-075-lambda-handler-that-validates-and-record","sec":"cloudwatch-s076","q":"How does the X-Ray Lambda handler validate input before writing to DynamoDB?","a":"<p>It raises a <code>ValueError</code> when <code>key_id</code> is missing:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if &#x27;key_id&#x27; not in event:\n    raise ValueError(&quot;Missing key ID in the item&quot;)</code></pre></div>","hand":true},{"id":"cloudwatch-f0204","card":"q-cloudwatch-075-lambda-handler-that-validates-and-record","sec":"cloudwatch-s076","q":"How does the Lambda handler return an error and record it in X-Ray?","a":"<p>It records the exception and returns status 400:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>xray_recorder.record_exception(e)\nreturn {&#x27;statusCode&#x27;: 400, &#x27;body&#x27;: json.dumps({&#x27;error&#x27;: str(e)})}</code></pre></div>","hand":true},{"id":"cloudwatch-f0205","card":"q-cloudwatch-075-lambda-handler-that-validates-and-record","sec":"cloudwatch-s076","q":"How does the handler write the item to DynamoDB?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>dynamodb.put_item(\n    TableName=&#x27;Items&#x27;,\n    Item={\n        &#x27;key_id&#x27;: {&#x27;S&#x27;: event[&#x27;key_id&#x27;]},\n        &#x27;data&#x27;: {&#x27;S&#x27;: event.get(&#x27;data&#x27;, &#x27;default&#x27;)}\n    }\n)</code></pre></div>","hand":true},{"id":"cloudwatch-f0206","card":"q-cloudwatch-076-what-rum-collects","sec":"cloudwatch-s077","q":"What is CloudWatch RUM?","a":"<p>Real User Monitoring gathers performance data from the end-user perspective, which is more accurate than internal network testing.</p>","hand":true},{"id":"cloudwatch-f0207","card":"q-cloudwatch-076-what-rum-collects","sec":"cloudwatch-s077","q":"How does RUM work?","a":"<p>A small RUM SDK injected into the web app sends data to CloudWatch RUM, which stores it and provides visualization.</p>","hand":true},{"id":"cloudwatch-f0208","card":"q-cloudwatch-076-what-rum-collects","sec":"cloudwatch-s077","q":"What data does RUM collect?","a":"<p>Page load times (how long users wait). JavaScript errors during interactions. HTTP requests: failed requests only. Browsers and devices: which are most used and which have issues. User behavior: time on pages, navigation, exit points.</p>","hand":true},{"id":"cloudwatch-f0209","card":"q-cloudwatch-077-script-tag-form-of-the-sdk","sec":"cloudwatch-s078","q":"How does the script-tag form of the RUM SDK load the code?","a":"<p>It creates an async script element that loads <code>rum.js</code> from the RUM endpoint:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>s.src = &quot;https://&lt;aws-rum-endpoint&gt;/rum.js&quot;;\ns.async = true;\ndocument.head.appendChild(s);</code></pre></div>","hand":true},{"id":"cloudwatch-f0210","card":"q-cloudwatch-077-script-tag-form-of-the-sdk","sec":"cloudwatch-s078","q":"Is the script-tag RUM snippet ready for production?","a":"<p>No. It is a conceptual snippet; copy the real snippet from the app monitor.</p>","hand":true},{"id":"cloudwatch-f0211","card":"q-cloudwatch-078-creating-an-app-monitor","sec":"cloudwatch-s079","q":"How do you create a RUM app monitor?","a":"<p>CloudWatch &gt; Application monitoring &gt; RUM &gt; Add app monitor.</p>","hand":true},{"id":"cloudwatch-f0212","card":"q-cloudwatch-078-creating-an-app-monitor","sec":"cloudwatch-s079","q":"Which settings does a RUM app monitor have?","a":"<p>Name (<code>demoapp</code>), application domain (<code>localhost</code> for development, the real URL in production), data collection defaults (performance telemetry, JavaScript errors, HTTP errors), cookies, session sampling and authorization through an identity pool.</p>","hand":true},{"id":"cloudwatch-f0213","card":"q-cloudwatch-078-creating-an-app-monitor","sec":"cloudwatch-s079","q":"Why lower the session sampling in production, and why create a new identity pool for the demo?","a":"<p>Lower sampling saves cost. A new identity pool skips a manual Cognito setup.</p>","hand":true},{"id":"cloudwatch-f0214","card":"q-cloudwatch-079-wiring-rum-into-a-vue-app","sec":"cloudwatch-s080","q":"Which commands install the RUM web SDK in the Vue demo app?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm install aws-rum-web\nnpm install</code></pre></div>","hand":true},{"id":"cloudwatch-f0215","card":"q-cloudwatch-079-wiring-rum-into-a-vue-app","sec":"cloudwatch-s080","q":"Which config keys does <code>registerRum.ts</code> use to set up <code>AwsRum</code>?","a":"<p><code>appId</code>, <code>appVersion</code>, <code>identityPoolId</code>, <code>endpoint</code> and <code>telemetries</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const config = {\n  appId: &#x27;&lt;your-app-monitor-id&gt;&#x27;,\n  appVersion: &#x27;1.0.0&#x27;,\n  identityPoolId: &#x27;&lt;your-identity-pool-id&gt;&#x27;,\n  endpoint: &#x27;https://&lt;aws-rum-endpoint&gt;&#x27;,\n  telemetries: [&#x27;performance&#x27;, &#x27;errors&#x27;, &#x27;http&#x27;]\n};\nconst rum = new AwsRum(config);</code></pre></div>","hand":true},{"id":"cloudwatch-f0216","card":"q-cloudwatch-079-wiring-rum-into-a-vue-app","sec":"cloudwatch-s080","q":"How do you start the Vue RUM demo and which address does it use?","a":"<p>Run <code>npm run serve</code> and open <code>http://localhost:8080</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>npm run serve</code></pre></div>","hand":true},{"id":"cloudwatch-f0217","card":"q-cloudwatch-079-wiring-rum-into-a-vue-app","sec":"cloudwatch-s080","q":"What does the Vue RUM demo do when you send requests?","a":"<p>It sends a configurable number of requests (for example 100) to a public JSON placeholder API, and every third one fails and throws.</p>","hand":true},{"id":"cloudwatch-f0218","card":"q-cloudwatch-079-wiring-rum-into-a-vue-app","sec":"cloudwatch-s080","q":"How long does RUM data take to appear, and what do you do if it does not?","a":"<p>About 5 minutes on the app monitor Overview. Open the browser Network console, check the requests to the app monitor, and read the Preview tab for errors.</p>","hand":true},{"id":"cloudwatch-f0219","card":"q-cloudwatch-079-wiring-rum-into-a-vue-app","sec":"cloudwatch-s080","q":"Do uncaught runtime errors in the Vue dev server stop RUM collection?","a":"<p>No. They are normal and do not stop RUM collection.</p>","hand":true},{"id":"cloudwatch-f0220","card":"q-cloudwatch-080-performance-and-web-vitals","sec":"cloudwatch-s081","q":"What does the RUM Performance tab show?","a":"<p>Page load times, errors and average load time by time of day. The default time range is 1 week.</p>","hand":true},{"id":"cloudwatch-f0221","card":"q-cloudwatch-080-performance-and-web-vitals","sec":"cloudwatch-s081","q":"Which web vitals does RUM show?","a":"<p>Largest Contentful Paint (LCP), First Input Delay (FID), Cumulative Layout Shift (CLS), and page load steps over time. They are similar to Lighthouse.</p>","hand":true},{"id":"cloudwatch-f0222","card":"q-cloudwatch-080-performance-and-web-vitals","sec":"cloudwatch-s081","q":"What do red metrics in RUM web vitals mean, and why improve vitals?","a":"<p>Red metrics indicate problems. Better vitals improve the experience and SEO ranking.</p>","hand":true},{"id":"cloudwatch-f0223","card":"q-cloudwatch-081-errors","sec":"cloudwatch-s082","q":"How does the RUM Errors tab organise errors?","a":"<p>Errors are grouped by page. Each shows metadata, user and session IDs (via Cognito), the message, file name and stack trace.</p>","hand":true},{"id":"cloudwatch-f0224","card":"q-cloudwatch-081-errors","sec":"cloudwatch-s082","q":"Which function throws the demo error in the RUM Vue app?","a":"<p><code>submitMultiplePosts</code> in <code>HomeView.vue</code>, which throws on every third request:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>if (i % 3 === 0) {\n  throw new Error(&#x27;Demo error for RUM&#x27;);\n}</code></pre></div>","hand":true},{"id":"cloudwatch-f0225","card":"q-cloudwatch-082-other-rum-tabs","sec":"cloudwatch-s083","q":"What does the RUM HTTP requests tab show?","a":"<p>Only failed requests (for example a <code>PUT</code> returning <code>404 Not Found</code>), to find API or network issues.</p>","hand":true},{"id":"cloudwatch-f0226","card":"q-cloudwatch-082-other-rum-tabs","sec":"cloudwatch-s083","q":"What do the RUM Sessions and Events tabs show?","a":"<p>Sessions: each app instance creates a session; open a session ID for page views and events. Events: HTTP events, JavaScript error events and other telemetries, chosen by <code>telemetries: ['performance', 'errors', 'http']</code> in <code>registerRum.ts</code>.</p>","hand":true},{"id":"cloudwatch-f0227","card":"q-cloudwatch-082-other-rum-tabs","sec":"cloudwatch-s083","q":"What do the RUM Browsers and devices and User journeys tabs show?","a":"<p>Browsers and devices: spot issues tied to a device or browser once live. User journeys: navigation across pages. Empty in the single-page demo; multi-page tracking needs extra configuration.</p>","hand":true},{"id":"cloudwatch-f0228","card":"q-cloudwatch-083-what-internet-monitor-does","sec":"cloudwatch-s084","q":"What problem does CloudWatch Internet Monitor solve?","a":"<p>Internet issues (slow or interrupted connectivity) hurt user experience, and traditional diagnosis can take days. Internet Monitor resolves issues in minutes.</p>","hand":true},{"id":"cloudwatch-f0229","card":"q-cloudwatch-083-what-internet-monitor-does","sec":"cloudwatch-s084","q":"How does Internet Monitor work?","a":"<p>It uses AWS global networking data to set a baseline for internet-facing traffic performance and availability, and gives a global view of internet health.</p>","hand":true},{"id":"cloudwatch-f0230","card":"q-cloudwatch-083-what-internet-monitor-does","sec":"cloudwatch-s084","q":"What does Internet Monitor tell you when an issue occurs?","a":"<p>It produces alerts with global context, and tells you whether an issue is on your side or the customer side with recommended actions. It adds worldwide traffic and performance data to CloudWatch.</p>","hand":true},{"id":"cloudwatch-f0231","card":"q-cloudwatch-084-creating-a-monitor","sec":"cloudwatch-s085","q":"What are the steps to create an Internet Monitor monitor?","a":"<p>CloudWatch &gt; Application monitoring &gt; Internet Monitor &gt; Create monitor.</p>\n<ol>\n  <li>Name it.</li>\n  <li>Add resources.</li>\n  <li>Set the percentage of internet traffic to monitor (100% if unsure).</li>\n  <li>Optionally publish internet measurements to an S3 bucket with a prefix.</li>\n  <li>Review and create.</li>\n</ol>","hand":true},{"id":"cloudwatch-f0232","card":"q-cloudwatch-084-creating-a-monitor","sec":"cloudwatch-s085","q":"Which resources can an Internet Monitor monitor?","a":"<p>Amazon VPCs, CloudFront distributions, Network Load Balancers or WorkSpaces directories.</p>","hand":true},{"id":"cloudwatch-f0233","card":"q-cloudwatch-084-creating-a-monitor","sec":"cloudwatch-s085","q":"How long does Internet Monitor take to show data, and what if there is no traffic?","a":"<p>The first data appears after about 10 minutes and meaningful data after a few hours. With no traffic there is no data.</p>","hand":true},{"id":"cloudwatch-f0234","card":"q-cloudwatch-084-creating-a-monitor","sec":"cloudwatch-s085","q":"How do you create traffic for Internet Monitor, and what do you do when finished?","a":"<p>Use the serverless API with a request tool, or CloudWatch canaries. Delete the monitor when finished to avoid charges.</p>","hand":true},{"id":"cloudwatch-f0235","card":"q-cloudwatch-085-generating-traffic","sec":"cloudwatch-s086","q":"Which Python loop sends repeated GET requests to the API to create Internet Monitor traffic?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>for i in range(num_requests):\n    try:\n        response = requests.get(api_url)\n        print(f&quot;Request {i+1} - Status: {response.status_code}&quot;)\n    except Exception as e:\n        print(f&quot;Request {i+1} failed: {e}&quot;)\n    time.sleep(0.1)</code></pre></div>","hand":true},{"id":"cloudwatch-f0236","card":"q-cloudwatch-085-generating-traffic","sec":"cloudwatch-s086","q":"How many requests does the Internet Monitor traffic script send?","a":"<p>1000:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>num_requests = 1000</code></pre></div>","hand":true},{"id":"cloudwatch-f0237","card":"q-cloudwatch-086-reading-the-monitor","sec":"cloudwatch-s087","q":"What does the Internet Monitor Overview show?","a":"<p>Percentage of traffic monitored, availability score, performance score, status <code>active</code>.</p>","hand":true},{"id":"cloudwatch-f0238","card":"q-cloudwatch-086-reading-the-monitor","sec":"cloudwatch-s087","q":"What do Traffic health scores and Internet traffic overview show?","a":"<p>Traffic health scores: a timeline of health events; none means normal. Internet traffic overview: a map of traffic origins that shows regions with bottlenecks.</p>","hand":true},{"id":"cloudwatch-f0239","card":"q-cloudwatch-086-reading-the-monitor","sec":"cloudwatch-s087","q":"What does the Internet Monitor Historical explorer show?","a":"<p>Trends over time with performance score, availability score, bytes transferred and round-trip time. They can be filtered by AWS location, country, subdivision, metro, city or network provider.</p>","hand":true},{"id":"cloudwatch-f0240","card":"q-cloudwatch-086-reading-the-monitor","sec":"cloudwatch-s087","q":"What do Internet Monitor Traffic insights show?","a":"<p>Total traffic in and out, top client locations and optimization suggestions. An example is moving an EC2 instance from us-east-1 to ca-central when most traffic comes from that area.</p>","hand":true},{"id":"cloudwatch-f0241","card":"q-cloudwatch-087-internet-monitor-alarm-and-api","sec":"cloudwatch-s088","q":"Which boto3 call reads the status of an Internet Monitor monitor?","a":"<p><code>get_monitor</code> on the <code>internetmonitor</code> client:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>internet_monitor = boto3.client(&#x27;internetmonitor&#x27;)\nresponse = internet_monitor.get_monitor(MonitorName=&#x27;demo2&#x27;)\nprint(response[&#x27;Status&#x27;])</code></pre></div>","hand":true},{"id":"cloudwatch-f0242","card":"q-cloudwatch-087-internet-monitor-alarm-and-api","sec":"cloudwatch-s088","q":"Which alarm settings alert when Internet Monitor latency exceeds 200 ms?","a":"<p>Namespace <code>AWS/InternetMonitor</code>, metric <code>Latency</code>, Average over 300 seconds, threshold 200, <code>GreaterThanThreshold</code>:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>AlarmName=&#x27;InternetMonitorLatencyAlert&#x27;,\nMetricName=&#x27;Latency&#x27;,\nNamespace=&#x27;AWS/InternetMonitor&#x27;,\nStatistic=&#x27;Average&#x27;,\nPeriod=300,\nEvaluationPeriods=1,\nThreshold=200,\nComparisonOperator=&#x27;GreaterThanThreshold&#x27;,</code></pre></div>","hand":true},{"id":"cloudwatch-f0243","card":"q-cloudwatch-088-critical-application-metric-not-appearin","sec":"cloudwatch-s089","q":"A critical application metric is not appearing in CloudWatch. What do you check?","a":"<p>Verify the metric is being published, the IAM permission <code>cloudwatch:PutMetricData</code>, the namespace, and the agent or SDK configuration.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import boto3\nclient = boto3.client(&#x27;cloudwatch&#x27;, region_name=&#x27;us-east-1&#x27;)\nclient.put_metric_data(\n    Namespace=&#x27;MyApp&#x27;,\n    MetricData=[{\n        &#x27;MetricName&#x27;: &#x27;CriticalMetric&#x27;,\n        &#x27;Value&#x27;: 100.0,\n        &#x27;Unit&#x27;: &#x27;Count&#x27;,\n        &#x27;Dimensions&#x27;: [{&#x27;Name&#x27;: &#x27;InstanceId&#x27;, &#x27;Value&#x27;: &#x27;i-1234567890abcdef0&#x27;}]\n    }]\n)</code></pre></div>\n<p>Console: CloudWatch &gt; Metrics &gt; All metrics, search <code>MyApp</code>/<code>CriticalMetric</code>. If missing, check Systems Manager Parameter Store or EC2 for the agent config, and the role in IAM &gt; Roles.</p>","hand":false},{"id":"cloudwatch-f0244","card":"q-cloudwatch-089-delayed-ec2-metrics","sec":"cloudwatch-s090","q":"CloudWatch metrics for an EC2 instance arrive late. Why?","a":"<p>Check the agent configuration, network latency and the collection interval.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;metrics&quot;: {\n    &quot;namespace&quot;: &quot;CWAgent&quot;,\n    &quot;metrics_collected&quot;: {\n      &quot;cpu&quot;: {\n        &quot;measurement&quot;: [&quot;cpu_usage_active&quot;],\n        &quot;metrics_collection_interval&quot;: 10\n      }\n    }\n  }\n}</code></pre></div>\n<p>Update the <code>AmazonCloudWatch-agent</code> config in Systems Manager Parameter Store to lower <code>metrics_collection_interval</code>, then restart the agent:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a restart</code></pre></div>","hand":false},{"id":"cloudwatch-f0245","card":"q-cloudwatch-090-custom-metric-with-incomplete-data","sec":"cloudwatch-s091","q":"A custom metric shows incomplete data. What is the cause?","a":"<p>Check publishing frequency, application logs, throttling and timestamp accuracy, and handle publish errors.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import boto3\nclient = boto3.client(&#x27;cloudwatch&#x27;)\ntry:\n    client.put_metric_data(\n        Namespace=&#x27;MyApp&#x27;,\n        MetricData=[{&#x27;MetricName&#x27;: &#x27;CustomMetric&#x27;, &#x27;Value&#x27;: 50.0, &#x27;Unit&#x27;: &#x27;Count&#x27;}]\n    )\nexcept client.exceptions.InvalidParameterValueException as e:\n    print(f&quot;Error: {e}&quot;)</code></pre></div>\n<p>Console: look for gaps in <code>CustomMetric</code>, review application logs under Logs &gt; Log groups, and confirm <code>cloudwatch:PutMetricData</code>.</p>","hand":false},{"id":"cloudwatch-f0246","card":"q-cloudwatch-091-no-metrics-for-a-newly-launched-resource","sec":"cloudwatch-s092","q":"A new instance has no metrics. What now?","a":"<p>Make sure the CloudWatch agent is installed, the IAM permissions are right, and the namespace and region are correct.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo yum install amazon-cloudwatch-agent\nsudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-config-wizard\nsudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -a start</code></pre></div>\n<p>Console: check the namespace (for example <code>AWS/EC2</code>), run <code>AWS-ConfigureCloudWatchAgent</code> from Systems Manager &gt; Run Command, and attach <code>CloudWatchAgentServerPolicy</code> to the role.</p>","hand":false},{"id":"cloudwatch-f0247","card":"q-cloudwatch-092-metric-data-missing-for-certain-periods","sec":"cloudwatch-s093","q":"Metric data has gaps. What explains them?","a":"<p>Application downtime, publishing failures, API throttling or the retention period.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch list-metrics --namespace MyApp\naws cloudwatch get-metric-statistics --namespace MyApp --metric-name MyMetric --start-time 2025-07-01T00:00:00Z --end-time 2025-07-02T00:00:00Z --period 300 --statistics Average</code></pre></div>\n<p>Console: adjust the time range to find the gaps, and check application logs for downtime.</p>","hand":false},{"id":"cloudwatch-f0248","card":"q-cloudwatch-093-alarm-not-triggering","sec":"cloudwatch-s094","q":"An alarm does not fire although the threshold was breached. What do you verify?","a":"<p>The threshold, evaluation period, namespace, and SNS permissions.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch describe-alarms --alarm-names MyAlarm\naws cloudwatch get-metric-statistics --namespace MyApp --metric-name MyMetric --start-time 2025-07-01T00:00:00Z --end-time 2025-07-02T00:00:00Z --period 60 --statistics Average</code></pre></div>\n<p>Console: Alarms &gt; <code>MyAlarm</code> &gt; Details for the metric and threshold, Metrics to confirm the data really crosses the threshold, and confirm the SNS topic allows <code>sns:Publish</code>.</p>","hand":false},{"id":"cloudwatch-f0249","card":"q-cloudwatch-094-frequent-false-positives","sec":"cloudwatch-s095","q":"An alarm produces many false positives. How do you tune it?","a":"<p>Increase the evaluation period, adjust the threshold, or use anomaly detection.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch put-metric-alarm --alarm-name MyAlarm --metric-name CPUUtilization --namespace AWS/EC2 --threshold 80.0 --comparison-operator GreaterThanThreshold --evaluation-periods 3 --period 300 --statistic Average --alarm-actions arn:aws:sns:us-east-1:123456789012:MyTopic</code></pre></div>\n<p>Console: Alarms &gt; <code>MyAlarm</code> &gt; Modify &gt; raise Evaluation Periods (for example 3) and adjust the Threshold.</p>","hand":false},{"id":"cloudwatch-f0250","card":"q-cloudwatch-095-alarm-stuck-in-insufficient-data","sec":"cloudwatch-s096","q":"An alarm stays in INSUFFICIENT_DATA. Why?","a":"<p>The metric may not exist or has no data points, or the namespace or dimensions do not match.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch get-metric-statistics --namespace MyApp --metric-name MyMetric --start-time 2025-07-01T00:00:00Z --end-time 2025-07-02T00:00:00Z --period 60 --statistics Average</code></pre></div>\n<p>Console: check the metric in the alarm Details, verify data points under Metrics, and publish test data through the SDK or CLI.</p>","hand":false},{"id":"cloudwatch-f0251","card":"q-cloudwatch-096-too-many-alarm-notifications","sec":"cloudwatch-s097","q":"Alarm notifications are too frequent. What do you change?","a":"<p>Lengthen the evaluation period or period, and adjust the threshold.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch put-metric-alarm --alarm-name MyAlarm --metric-name ErrorRate --namespace MyApp --threshold 10.0 --comparison-operator GreaterThanThreshold --evaluation-periods 5 --period 300 --statistic Average --alarm-actions arn:aws:sns:us-east-1:123456789012:MyTopic</code></pre></div>\n<p>Console: Alarms &gt; <code>MyAlarm</code> &gt; Modify &gt; set Evaluation Periods to 5 and Period to 300 seconds.</p>","hand":false},{"id":"cloudwatch-f0252","card":"q-cloudwatch-097-sns-notifications-not-delivered","sec":"cloudwatch-s098","q":"SNS notifications do not reach recipients. What do you check?","a":"<p>The topic subscription, IAM permissions and endpoint validity.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws sns list-subscriptions-by-topic --topic-arn arn:aws:sns:us-east-1:123456789012:MyTopic\naws sns publish --topic-arn arn:aws:sns:us-east-1:123456789012:MyTopic --message &quot;Test message&quot;</code></pre></div>\n<p>Console: SNS &gt; Topics &gt; <code>MyTopic</code> &gt; Subscriptions to confirm the endpoint is confirmed, check the topic ARN on the alarm, and publish a test message from the SNS console.</p>","hand":false},{"id":"cloudwatch-f0253","card":"q-cloudwatch-098-logs-not-appearing-in-cloudwatch-logs","sec":"cloudwatch-s099","q":"Application logs are not showing up. What do you verify?","a":"<p>Agent configuration, IAM permissions, and the log group and stream.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo cat /opt/aws/amazon-cloudwatch-agent/etc/amazon-cloudwatch-agent.json\naws logs describe-log-groups --log-group-name-prefix my-app-logs</code></pre></div>\n<p>Agent log collection config:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;logs&quot;: {\n    &quot;logs_collected&quot;: {\n      &quot;files&quot;: {\n        &quot;collect_list&quot;: [\n          {\n            &quot;file_path&quot;: &quot;/var/log/application.log&quot;,\n            &quot;log_group_name&quot;: &quot;my-app-logs&quot;,\n            &quot;log_stream_name&quot;: &quot;{instance_id}&quot;\n          }\n        ]\n      }\n    }\n  }\n}</code></pre></div>\n<p>Required IAM statement:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;Effect&quot;: &quot;Allow&quot;,\n  &quot;Action&quot;: [&quot;logs:CreateLogGroup&quot;, &quot;logs:CreateLogStream&quot;, &quot;logs:PutLogEvents&quot;],\n  &quot;Resource&quot;: &quot;arn:aws:logs:region:account-id:log-group:my-app-logs:*&quot;\n}</code></pre></div>\n<p>Check the agent status:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -m ec2 -a status</code></pre></div>\n<p>Also confirm the <code>my-app-logs</code> group exists and the role has <code>logs:PutLogEvents</code>.</p>","hand":false},{"id":"cloudwatch-f0254","card":"q-cloudwatch-099-duplicate-log-entries","sec":"cloudwatch-s100","q":"Log entries are duplicated. What is the usual cause?","a":"<p>Several writers send the same logs. Check for more than one agent process or an application logger that also ships logs, and keep a single stream.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo ps aux | grep amazon-cloudwatch-agent\nsudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -m ec2 -a stop</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JavaScript</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>const winston = require(&#x27;winston&#x27;);\nconst { CloudWatchLogs } = require(&#x27;winston-cloudwatch&#x27;);\nconst logger = winston.createLogger({\n  transports: [\n    new CloudWatchLogs({\n      logGroupName: &#x27;my-app-logs&#x27;,\n      logStreamName: &#x27;app-stream&#x27;,\n      awsRegion: &#x27;us-east-1&#x27;\n    })\n  ]\n});</code></pre></div>\n<p>Check <code>my-app-logs</code> for duplicate streams and review the application code or agent config.</p>","hand":false},{"id":"cloudwatch-f0255","card":"q-cloudwatch-100-delayed-log-data","sec":"cloudwatch-s101","q":"Log data arrives late. What do you do?","a":"<p>Check agent metrics and increase the buffer.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch get-metric-statistics --namespace AWS/Logs --metric-name IncomingLogEvents --dimensions Name=LogGroupName,Value=my-app-logs --start-time $(date -u -Iseconds -d &#x27;-1 hour&#x27;) --end-time $(date -u -Iseconds) --period 300 --statistics Sum</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;logs&quot;: {\n    &quot;logs_collected&quot;: {\n      &quot;files&quot;: {\n        &quot;collect_list&quot;: [\n          {\n            &quot;file_path&quot;: &quot;/var/log/application.log&quot;,\n            &quot;log_group_name&quot;: &quot;my-app-logs&quot;,\n            &quot;log_stream_name&quot;: &quot;{instance_id}&quot;,\n            &quot;buffer_duration&quot;: 5000\n          }\n        ]\n      }\n    }\n  }\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -m ec2 -a start</code></pre></div>\n<p>Look at <code>IncomingLogEvents</code> under AWS/Logs, then update the agent config on the instance.</p>","hand":false},{"id":"cloudwatch-f0256","card":"q-cloudwatch-101-logs-insights-query-returning-incomplete","sec":"cloudwatch-s102","q":"A Logs Insights query returns incomplete results. How do you fix it?","a":"<p>Verify the syntax and time range, and optimize the filters.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Logs</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>fields @timestamp, @message\n| filter @message like /ERROR/\n| sort @timestamp desc\n| limit 100</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws logs start-query --log-group-name my-app-logs --start-time $(date -d &quot;-1 hour&quot; +%s) --end-time $(date +%s) --query-string &#x27;fields @timestamp, @message | filter @message like /ERROR/&#x27;</code></pre></div>\n<p>Console: Logs &gt; Logs Insights &gt; select <code>my-app-logs</code>, widen the time range and refine the filters.</p>","hand":false},{"id":"cloudwatch-f0257","card":"q-cloudwatch-102-log-groups-causing-storage-issues","sec":"cloudwatch-s103","q":"Log groups are growing and costing storage. What do you do?","a":"<p>Set a retention policy and export old data to S3.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws logs put-retention-policy --log-group-name my-app-logs --retention-in-days 7\naws logs create-export-task --log-group-name my-app-logs --from $(date -d &quot;-30 days&quot; +%s000) --to $(date +%s000) --destination my-s3-bucket --destination-prefix logs</code></pre></div>\n<p>Console: Logs &gt; <code>my-app-logs</code> &gt; Actions &gt; Edit retention (7 days), and Actions &gt; Export data to S3 with a time range and bucket.</p>","hand":false},{"id":"cloudwatch-f0258","card":"q-cloudwatch-103-user-cannot-view-metrics","sec":"cloudwatch-s104","q":"A user cannot view CloudWatch metrics. What is missing?","a":"<p>IAM permissions such as <code>cloudwatch:GetMetricData</code> and <code>cloudwatch:ListMetrics</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;Effect&quot;: &quot;Allow&quot;,\n  &quot;Action&quot;: [&quot;cloudwatch:GetMetricData&quot;, &quot;cloudwatch:ListMetrics&quot;, &quot;cloudwatch:DescribeAlarms&quot;],\n  &quot;Resource&quot;: &quot;*&quot;\n}</code></pre></div>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws iam get-user-policy --user-name user-name</code></pre></div>\n<p>Add the permission under IAM &gt; Users &gt; user-name &gt; Permissions, then test in CloudWatch &gt; Metrics.</p>","hand":false},{"id":"cloudwatch-f0259","card":"q-cloudwatch-104-agent-not-sending-metrics","sec":"cloudwatch-s105","q":"The CloudWatch agent is not sending metrics. What do you check?","a":"<p>Agent status, configuration, and restart it.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -m ec2 -a status</code></pre></div>\n<p>Edit <code>/opt/aws/amazon-cloudwatch-agent/etc/amazon-cloudwatch-agent.json</code> (set the namespace, for example <code>CustomMetrics</code>, and <code>metrics_collected</code> such as <code>cpu</code> with <code>cpu_usage_active</code>), restart, and verify the namespace in CloudWatch &gt; Metrics:</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sudo /opt/aws/amazon-cloudwatch-agent/bin/amazon-cloudwatch-agent-ctl -m ec2 -a start</code></pre></div>","hand":false},{"id":"cloudwatch-f0260","card":"q-cloudwatch-105-quota-blocking-a-new-alarm","sec":"cloudwatch-s106","q":"A quota limit prevents creating a new alarm. What do you do?","a":"<p>Check the quota and request an increase.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws service-quotas list-service-quotas --service-code cloudwatch\naws service-quotas request-service-quota-increase --service-code cloudwatch --quota-code L-12345678 --desired-value 1000</code></pre></div>\n<p>Console: Service Quotas &gt; AWS services &gt; Amazon CloudWatch &gt; Alarms &gt; Request quota increase.</p>","hand":false},{"id":"cloudwatch-f0261","card":"q-cloudwatch-106-slow-dashboards","sec":"cloudwatch-s107","q":"CloudWatch dashboards load slowly. What helps?","a":"<p>Reduce widget complexity (fewer metrics per widget) and use longer periods.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;widgets&quot;: [\n    {\n      &quot;type&quot;: &quot;metric&quot;,\n      &quot;properties&quot;: {\n        &quot;metrics&quot;: [[&quot;AWS/EC2&quot;, &quot;CPUUtilization&quot;, &quot;InstanceId&quot;, &quot;i-1234567890abcdef0&quot;]],\n        &quot;period&quot;: 300,\n        &quot;stat&quot;: &quot;Average&quot;\n      }\n    }\n  ]\n}</code></pre></div>\n<p>Console: Dashboards &gt; Edit widgets &gt; reduce metrics and raise the period (for example 300 seconds).</p>","hand":false},{"id":"cloudwatch-f0262","card":"q-cloudwatch-107-high-api-request-latency","sec":"cloudwatch-s108","q":"CloudWatch API requests are slow. What do you do?","a":"<p>Check for throttling and enable metric streams.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Bash</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>aws cloudwatch get-metric-statistics --namespace AWS/CloudWatch --metric-name ThrottledRequests --start-time $(date -u -Iseconds -d &#x27;-1 hour&#x27;) --end-time $(date -u -Iseconds) --period 300 --statistics Sum\naws cloudwatch create-metric-stream --name my-metric-stream --role-arn arn:aws:iam::account-id:role/my-stream-role --firehose-arn arn:aws:firehose:region:account-id:deliverystream/my-stream --output-format opentelemetry</code></pre></div>\n<p>Console: check <code>ThrottledRequests</code> under AWS/CloudWatch, then Metric streams &gt; create a stream with Kinesis Firehose.</p>","hand":false},{"id":"cloudwatch-f0263","card":"q-cloudwatch-108-high-metric-costs","sec":"cloudwatch-s109","q":"CloudWatch metric costs are high. How do you cut them?","a":"<p>Reduce collection frequency and stop publishing unused metrics.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;metrics&quot;: {\n    &quot;namespace&quot;: &quot;CustomMetrics&quot;,\n    &quot;metrics_collected&quot;: {\n      &quot;cpu&quot;: {\n        &quot;measurement&quot;: [&quot;cpu_usage_active&quot;],\n        &quot;metrics_collection_interval&quot;: 300\n      }\n    }\n  }\n}</code></pre></div>\n<p>Find high-frequency metrics under CloudWatch &gt; Metrics &gt; <code>CustomMetrics</code> and update the agent config on the instance. CloudWatch has no delete-metric API; a metric you stop publishing simply expires after its retention window, so stopping the publisher is what removes the cost.</p>","hand":false}];
